// The Serbo-Croatian of What's new, what each version changed (lib/whats-new.ts, app/whats-new.tsx) (i18n/sh/index.ts).
export const whatsNew: Record<string, string> = {
  "What's new": 'Šta je novo',
  'What each version changed': 'Šta je promijenila svaka verzija',
  'What each version of Erevos changed, the newest first.': 'Šta je promijenila svaka verzija Erevosa, najnovija prva.',
  'Not out yet': 'Još nije izašla',
  'This version': 'Ova verzija',
  'For you': 'Za vas',
  'Under the hood': 'Ispod haube',
  // Not out yet.
  "**Linked devices on the same Wi-Fi**: the phone and a computer on the same Wi-Fi or hotspot give each other what changes straight there, with no internet too. See [Linked devices](#devices).":
    "**Povezani uređaji na istom Wi-Fiju**: telefon i računar na istom Wi-Fiju ili hotspotu daju jedno drugom ono što se mijenja direktno tamo, i bez interneta. Vidi [Povezani uređaji](#devices).",
  "**Your Matrix, XMPP and Nostr accounts on every linked device**: each device linked gets them by itself, with no choice to make, and they follow as they change on the phone: one you sign out of there, or replace with another, goes from the devices too. See [Linked devices](#devices).":
    "**Tvoji računi Matrix, XMPP i Nostr na svakom povezanom uređaju**: svaki povezani uređaj dobija ih sam, bez biranja, i prate promjene na telefonu: račun iz kojeg se tamo odjaviš, ili ga zamijeniš drugim, nestaje i s uređaja. Vidi [Povezani uređaji](#devices).",
  "**Same settings on your linked devices**: the language, the look and Last seen changed on the phone or a computer change on the others too. A photo behind the screens, passwords, PINs and what is about one device alone stay on each. A device can keep its own: **Same settings on every device** in Linked devices. See [Linked devices](#devices).":
    "**Iste postavke na tvojim povezanim uređajima**: jezik, izgled i Posljednji put viđen promijenjeni na telefonu ili računaru mijenjaju se i na drugima. Fotografija iza ekrana, lozinke, PIN-ovi i ono što se tiče samo jednog uređaja ostaju na svakom. Uređaj može zadržati svoje: **Iste postavke na svim uređajima** u Povezanim uređajima. Vidi [Povezani uređaji](#devices).",
  "**Last seen**: when a contact is not online, their chat says when they last had Erevos open, to the minute. It goes end-to-end encrypted, never to the relay. It is on, and both ways: turn it off in Settings → Privacy and security → Last seen, and no one sees yours, nor you theirs. Hidden chats have their own time and their own switch, in a chat's details there. See [Chat through a relay](#relay).":
    "**Posljednji put viđen**: kad kontakt nije na mreži, njegov razgovor kaže kad je posljednji put imao otvoren Erevos, na minut tačno. Ide šifrirano s kraja na kraj, nikad relayu. Uključeno je, i u oba smjera: isključite ga u Postavke → Privatnost i sigurnost → Posljednji put viđen, i niko ne vidi vaše, a ni vi njihovo. Skriveni razgovori imaju vlastito vrijeme i vlastiti prekidač, u detaljima razgovora tamo. Pogledajte [Razgovor preko relaya](#relay).",
  "**One Public feed**: the new **Public** chip on the home screen shows the public posts of the Nostr people you follow and the public Matrix rooms you are in as one feed, as in Amethyst, with photos inside the posts and a card for a link. Answer, share again, like, share and write new posts with photos; for Matrix, answer, react and share. **Photos** chooses whether photos come at once, only through Tor or on a tap. The **Nostr** chip shows only the Nostr chats again. See [Chats with other Nostr apps](#nostr-chats).":
    "**Jedan javni feed**: novo dugme **Javno** na početnom ekranu prikazuje u jednom feedu, kao u Amethystu, javne objave Nostr ljudi koje pratite i javne Matrix sobe u kojima ste, s fotografijama u objavama i karticom za vezu. Odgovorite, ponovo podijelite, označite da vam se sviđa, podijelite i pišite nove objave s fotografijama; kod Matrixa odgovorite, reagujte i podijelite. **Fotografije** biraju hoće li fotografije stići odmah, samo preko Tora ili na dodir. Dugme **Nostr** opet prikazuje samo Nostr razgovore. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Collection**: an encrypted place in every space and hidden place for photos, files and folders, with its icon next to the lock. Turn it on in Modules. See [Collection](#collection).":
    "**Zbirka**: šifrirano mjesto u svakom prostoru i skrivenom mjestu za fotografije, datoteke i foldere, s ikonom pored lokota. Uključite je u Modulima. Pogledajte [Zbirku](#collection).",
  "**Music, videos and PDFs in the Collection**: music and videos play from their encrypted pieces, music on with the screen off and with play, pause, next and previous on the lock screen, and PDFs read page by page inside Erevos. **Open with another app** leaves no plain copy, and a photo or video picked from the gallery can be deleted there after importing. See [Collection](#collection).":
    "**Muzika, video i PDF u Zbirci**: muzika i video se reproduciraju iz svojih šifriranih dijelova, muzika i s ugašenim ekranom, s reprodukcijom, pauzom, sljedećim i prethodnim na zaključanom ekranu, a PDF-ovi se čitaju stranicu po stranicu unutar Erevosa. **Otvori drugom aplikacijom** ne ostavlja nešifriranu kopiju, a fotografija ili video iz galerije može se nakon uvoza tamo izbrisati. Pogledajte [Zbirku](#collection).",
  "**The Collection on a computer**: in the desktop app for Linux, macOS and Windows the Collection keeps your photos and files encrypted too. Photos, PDFs, music and videos open in memory only, never as a plain copy on the disk, and close when the space locks. **Save to the computer** asks first. See [Collection](#collection).":
    "**Zbirka na računaru**: u aplikaciji za računar za Linux, macOS i Windows Zbirka i tamo čuva vaše fotografije i datoteke šifrirane. Fotografije, PDF-ovi, muzika i video otvaraju se samo u memoriji, nikad kao nešifrirana kopija na disku, i zatvaraju se kad se prostor zaključa. **Spremi na računar** prvo pita. Pogledajte [Zbirku](#collection).",
  "**Files up to 4 GB in the Collection**: on Android a file picked from the phone's files is encrypted as it is read, with no plain copy first, so it comes in faster and needs no room twice. In the desktop app music and videos up to 1 GB play. See [Collection](#collection).":
    "**Datoteke do 4 GB u Zbirci**: na Androidu se datoteka odabrana iz datoteka telefona šifrira dok se čita, bez nešifrirane kopije prije, pa ulazi brže i ne treba dvostruko mjesta. U aplikaciji za računar puštaju se muzika i video do 1 GB. Pogledajte [Zbirku](#collection).",
  "**The Collection on a WebDAV server**: each space and hidden place can copy its Collection, still encrypted, to a folder on a server you choose, Nextcloud, ownCloud or any that speaks WebDAV, so big files are not only on the phone. Only what is new goes, and a phone that lacks a file fetches it from there. See [Collection](#collection).":
    "**Zbirka na WebDAV serveru**: svaki prostor i svako skriveno mjesto može kopirati svoju Zbirku, i dalje šifrovanu, u folder na serveru koji izabereš, Nextcloud, ownCloud ili bilo koji koji govori WebDAV, da velike datoteke ne budu samo na telefonu. Ide samo ono što je novo, a telefon kojem nedostaje datoteka uzima je odande. Vidi [Zbirka](#collection).",
  "**The Collection on your linked devices**: turn on **On my linked devices too** in a Collection's settings and that Collection goes to the space's or hidden place's linked devices, changes and deletions with it. Small pictures come at once, a file itself on the same Wi-Fi or when you open it, a piece at a time, going on where it stopped after the network drops. See [Collection](#collection).":
    "**Zbirka na tvojim povezanim uređajima**: uključi **I na mojim povezanim uređajima** u podešavanjima Zbirke i ta Zbirka ide na povezane uređaje prostora ili skrivenog mjesta, s promjenama i brisanjima. Sličice stižu odmah, sama datoteka na istom Wi-Fi-ju ili kad je otvoriš, komad po komad, nastavljajući gdje je stala kad mreža padne. Vidi [Zbirka](#collection).",
  "**Groups stay on the device you choose**: on the phone, under Linked devices → Groups stay on, move the groups to a linked computer. Their keys go there, never copied, so the groups work there with the phone off and new ones can be made there; members see nothing new. See [Linked devices](#devices).":
    "**Grupe ostaju na uređaju koji izabereš**: na telefonu, pod Povezani uređaji → Grupe ostaju na, premjesti grupe na povezani računar. Njihovi ključevi idu tamo, nikad kopirani, pa grupe tamo rade i kad je telefon isključen i tamo se mogu praviti nove; članovi ne vide ništa novo. Pogledaj [Povezani uređaji](#devices).",
  "**Add someone new on a linked device without the phone**: a computer adds someone whose contact link is from this version by itself, with the phone off, and writes to them at once; they see your account as a request, with the same safety number, and the phone adds them too once it is on. See [Linked devices](#devices).":
    "**Dodaj nekoga novog na povezanom uređaju bez telefona**: računar sam dodaje nekoga čiji je link kontakta iz ove verzije, kad je telefon isključen, i odmah mu piše; ta osoba vidi tvoj račun kao zahtjev, s istim sigurnosnim brojem, a telefon je dodaje i sam čim se uključi. Pogledaj [Povezani uređaji](#devices).",
  "**Calls and Send later on your linked devices without the phone**: with a contact on this version, a computer calls and is called by itself and sends a message for later itself, with the phone off, and a copy goes to each of their devices too, held till its time. Every device of yours shows what is scheduled, and deleting it on any of them takes it back everywhere. See [Linked devices](#devices).":
    "**Pozivi i Pošalji kasnije na povezanim uređajima bez telefona**: s kontaktom s ovom verzijom računar sam zove i prima pozive i sam šalje poruku za kasnije, i kad je telefon isključen, a kopija ide i na svaki njegov uređaj, čuvana do njenog vremena. Svaki vaš uređaj pokazuje šta je zakazano, a ako to obrišete na bilo kojem, povlači se svuda. Pogledajte [Povezani uređaji](#devices).",
  '**Support Erevos**: every way has its QR code now, Liberapay and PayPal too, and PayPal opens in the browser.':
    '**Podržite Erevos**: svaki način sada ima svoj QR kôd, i Liberapay i PayPal, a PayPal se otvara u pregledniku.',
  '**Chats open at their end**: a long chat, or one with imported messages, could open at a message read long ago, often a photo, as it drew earlier messages on its way to the end. Now it opens at the newest message, and the arrow to where you left off is there when new ones came.':
    '**Razgovori se otvaraju na svom kraju**: dugačak razgovor, ili onaj s uvezenim porukama, mogao se otvoriti na poruci pročitanoj davno, često na fotografiji, jer je na putu do kraja učitavao ranije poruke. Sada se otvara na najnovijoj poruci, a strelica tamo gdje je stalo tu je kad su stigle nove.',
  "**Tor off unless you turn it on**: a new space sends nothing through Tor, so messages go fastest, and turning Tor on asks first, as it makes them slower. A space you already have keeps its choice, under Settings → Relay and networks → Tor. Texts through Nostr now go without Tor too: then the Nostr relays see your phone's internet address, never who wrote to whom. See [Through Tor](#tor).":
    "**Tor je isključen dok ga ne uključiš**: novi prostor ne šalje ništa preko Tora, pa poruke idu najbrže, a uključivanje Tora prvo pita, jer ih usporava. Prostor koji već imaš zadržava svoj izbor, u Postavke → Relay i mreže → Tor. Tekstovi preko Nostra sada idu i bez Tora: tada Nostr relayi vide IP adresu tvog telefona, nikad tko je kome pisao. Vidi [Preko Tora](#tor).",
  "**Moving a chat to a space with no relay**: **Move to another space** stopped there, as that space had no relay of its own. Now it offers this space's relay, which that space then keeps, and it makes that space's relay queue when it has a relay but no queue yet. See [Second password](#second).":
    "**Premještanje razgovora u prostor bez relaya**: **Premjesti u drugi prostor** stajalo je tu, jer taj prostor nije imao svoj relay. Sada nudi relay ovog prostora, koji taj prostor zatim zadržava, i pravi red tog prostora na relayu kad ima relay, ali još nema red. Vidi [Druga lozinka](#second).",
  "**A home relay only through Tor**: switch a home relay to **Only through Tor** and it never sees your phone's address, whatever Tor is set to for the rest. With no token typed, it gives one for a coupon that your relay signs blind, so neither relay can tell whose it is, and two spaces can use each other's relays as home relays with nothing tying them together. The token comes within the hour, lasts 90 days, and Erevos renews it by itself. Needs Tor, on Android. See [Home relay](#home-relay).":
    '**Kućni relay samo preko Tora**: prebacite kućni relay na **Samo preko Tora** i on nikad ne vidi adresu vašeg telefona, bez obzira na to šta je za ostalo postavljeno u Toru. Bez upisanog tokena daje jedan za kupon koji vaš relay potpisuje naslijepo, pa nijedan relay ne može znati čiji je, a dva prostora mogu koristiti relaye jedan drugoga kao kućne relaye bez ičega što ih povezuje. Token stiže u roku od sat vremena, traje 90 dana, a Erevos ga sam obnavlja. Treba Tor, na Androidu. Vidi [Kućni relay](#home-relay).',
  // 6.0.0-rc.2
  "**Home's buttons stay at the bottom**: after the password, home's **Remind me** and **New chat** could float halfway up the screen, over the chats, with the list ending above them, until Erevos went away and came back. Now the screen asks Android at once whether a keyboard is open. See [Password lock](#lock).":
    "**Dugmad početnog ekrana ostaju dolje**: nakon lozinke, **Podsjeti me** i **Novi razgovor** mogli su lebdjeti na pola ekrana, preko razgovora, a lista se završavala iznad njih, dok se Erevos ne napusti i ponovo otvori. Sada ekran odmah pita Android da li je tastatura otvorena. Vidi [Zaključavanje lozinkom](#lock).",
  "**The Nostr tab's posts come**: **Posts** could stay on **Looking…** for good through Tor. Each wait through Tor took one of the threads the whole app shares, and once all were taken, every look-up of the posts waited behind the others; a relay that answered and then could not be reached kept them waiting with no end. Now Tor's waits have threads of their own, a relay that cannot be reached is let be after 20 seconds, and the posts come within about two minutes at most, with what was found by then. See [Chats with other Nostr apps](#nostr-chats).":
    "**Objave na kartici Nostr stižu**: **Objave** su preko Tora mogle zauvijek ostati na **Provjera…**. Svako čekanje preko Tora zauzimalo je jednu od niti koje dijeli cijela aplikacija, a kad su sve bile zauzete, svaka pretraga objava čekala je iza ostalih; relej koji je odgovorio pa više nije bio dostupan ostavljao ih je da čekaju bez kraja. Sada čekanja preko Tora imaju svoje niti, relej koji nije dostupan ostavlja se nakon 20 sekundi, a objave stižu najviše za oko dvije minute, s onim što je do tada pronađeno. Vidi [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Linux, Windows and macOS again**: 6.0.0-rc.1 came out without them: the check that each build for computers opens did not know the setup of Erevos's very first start. Now it does.":
    "**Ponovo Linux, Windows i macOS**: 6.0.0-rc.1 je izašla bez njih: provjera da se svaka verzija za računar otvara nije poznavala podešavanje pri sasvim prvom pokretanju Erevosa. Sada ga poznaje.",
  // 6.0.0-rc.1
  "**Links open on Sailfish OS**: **Sign in with LPHL**, a donation page or a link in a chat opened nothing there. Now Sailfish OS opens them: a web page in the browser, a number in the phone or the messages, an address in the mail.":
    "**Linkovi se otvaraju na Sailfish OS-u**: **Prijava preko LPHL**, stranica za donacije ili link u razgovoru tamo nisu otvarali ništa. Sada ih otvara Sailfish OS: web stranicu u pregledniku, broj u telefonu ili porukama, adresu u e-pošti.",
  "**Matrix, and photos and files in XMPP and Nostr chats, on Sailfish OS**: Erevos there could not reach their servers over HTTPS, so Matrix could not sign in, photos and files neither came nor went, and links showed no preview. Now they work as on a computer.":
    "**Matrix te fotografije i datoteke u XMPP i Nostr razgovorima na Sailfish OS-u**: tamo Erevos nije dolazio do njihovih servera preko HTTPS-a, pa se Matrix nije mogao prijaviti, fotografije i datoteke nisu ni stizale ni odlazile, a linkovi nisu prikazivali pregled. Sada rade kao na računalu.",
  "**A phone call shows its screen**: with Erevos as the phone app, a call that came could ring with the phone's screen black, so it could not be answered, when Android's full-screen notifications for Erevos, Erevos's notices or its notices of incoming calls were off. Now the call screen comes up by itself, over the lock screen too, and turns the screen on. A call that Do Not Disturb holds back still comes quietly, with the screen off. See [Phone](#phone).":
    "**Telefonski poziv prikazuje svoj ekran**: s Erevosom kao aplikacijom za telefon, dolazni poziv je mogao zvoniti uz crn ekran, pa se nije mogao prihvatiti, kad su bile isključene Androidove obavijesti preko cijelog ekrana za Erevos, obavijesti Erevosa ili njegove obavijesti o dolaznim pozivima. Sada se ekran poziva pojavljuje sam, i preko zaključanog ekrana, i pali ekran. Poziv koji „Ne uznemiravaj“ zadrži i dalje dolazi tiho, s ugašenim ekranom. Pogledajte [Telefon](#phone).",
  "**The calculator shows a long result from its start**: upright, a result with many decimals hid its first digits, which showed only with the phone turned sideways. Now a long number gets smaller to fit, its first digits always in sight.":
    "**Kalkulator prikazuje dug rezultat od početka**: uspravno, rezultat s mnogo decimala skrivao je prve cifre, koje su se vidjele samo s okrenutim telefonom. Sada se dug broj smanjuje dok ne stane, a prve cifre su uvijek vidljive.",
  "**Pick the recipient of a new SMS from your contacts**: **New SMS** has a **Contacts** button that opens your contacts with a search, and typing a name or number suggests the contacts that match. A contact with several numbers shows a line for each, and for a group MMS each one you pick is added. With only the SMS open, only the phone's contacts show. See [SMS](#sms).":
    "**Izaberite primaoca novog SMS-a iz kontakata**: **Novi SMS** ima dugme **Kontakti** koje otvara vaše kontakte uz pretragu, a dok kucate ime ili broj predlažu se kontakti koji odgovaraju. Kontakt s više brojeva prikazuje po jedan red za svaki, a u grupnom MMS-u se svaki izabrani kontakt dodaje. Kad su otvoreni samo SMS, prikazuju se samo kontakti telefona. Vidi [SMS](#sms).",
  "**More for a number in the Phone**: on the keypad, **⋯** beside a typed number offers **Add to contacts**, **Add to an existing contact**, **Send an SMS** and **Copy the number**. **Recents** and **Favourites** offer **Copy the number** and **Open the contact**; **Favourites** also **Send an SMS**, and **Recents** adds an unknown number to an existing contact. With Erevos locked, the Phone still only calls. See [Phone](#phone).":
    "**Više za broj u Telefonu**: na tastaturi **⋯** pored otkucanog broja nudi **Dodaj u kontakte**, **Dodaj postojećem kontaktu**, **Pošalji SMS** i **Kopiraj broj**. **Nedavni** i **Favoriti** nude **Kopiraj broj** i **Otvori kontakt**; **Favoriti** i **Pošalji SMS**, a **Nedavni** dodaju nepoznat broj postojećem kontaktu. Dok je Erevos zaključan, Telefon i dalje samo zove. Pogledajte [Telefon](#phone).",
  "**A short buzz on touch**: the keys of the keypad, **Call**, **End**, Send, the keyboard's Enter, switches and menus that open give a short buzz. **Settings** → **Appearance** → **Vibrate on touch** turns it off. See [Appearance](#appearance).":
    "**Kratka vibracija na dodir**: tipke na tastaturi, **Pozovi**, **Završi**, Pošalji, Enter na tastaturi, prekidači i meniji koji se otvaraju kratko vibriraju. U **Postavke** → **Izgled** → **Vibracija na dodir** to isključuješ. Pogledajte [Izgled](#appearance).",
  "**A number on each icon, on Huawei and Honor**: their launchers now show a number on each of Erevos's icons apart, with **Number on the icon** on: on Erevos's own the messages, on SMS's the SMS not read, on Phone's the missed calls, on Contacts's a birthday today. Most other launchers, such as those of Pixel and GrapheneOS, Samsung's and Kvaesitso, give a notice's dot or number to all of an app's icons alike, and Erevos cannot change that there. See [Appearance](#appearance).":
    "**Broj na svakoj ikoni, na Huaweiju i Honoru**: njihovi pokretači sada prikazuju broj na svakoj ikoni Erevosa posebno, uz uključen **Broj na ikoni**: na Erevosovoj poruke, na ikoni SMS nepročitane SMS poruke, na ikoni Telefon propuštene pozive, na ikoni Kontakti današnji rođendan. Većina drugih pokretača, poput onih na Pixelu i GrapheneOS-u, Samsungovog i Kvaesitsa, daje tačku ili broj obavijesti jednako svim ikonama aplikacije, i tu Erevos to ne može promijeniti. Pogledajte [Izgled](#appearance).",
  "**Choose the parts of Erevos you use**: Erevos's own chats, the Phone, the SMS, and the chats with Nostr, Matrix and XMPP apps are modules now, any of them on, Erevos's own too, at least one. One that is off does not start and shows nowhere, and the Phone's and the SMS's icons leave the phone's apps: Erevos is lighter, opens faster and uses less battery. Nothing of it is deleted: it is all there again when it is back on. Erevos's very first start sets it up as an installer does, its language, the modules and what Android should allow for them; a module turned on later asks for its permissions again. After this update every module stays on until you change them in **Settings** → **General** → **Modules**. See [Modules](#modules).":
    "**Izaberite dijelove Erevosa koje koristite**: vlastiti razgovori Erevosa, Telefon, SMS i razgovori s Nostr, Matrix i XMPP aplikacijama sada su moduli, bilo koji od njih može biti uključen, i vlastiti Erevosov, barem jedan. Isključen se ne pokreće i nigdje se ne prikazuje, a ikone Telefona i SMS-a nestaju među aplikacijama telefona: Erevos je lakši, brže se otvara i troši manje baterije. Ništa od njega se ne briše: sve je opet tu kad se ponovo uključi. Sasvim prvo pokretanje Erevosa postavlja ga kao instalater, jezik, module i ono što Android treba dozvoliti za njih; modul uključen kasnije ponovo traži svoje dozvole. Nakon ovog ažuriranja svaki modul ostaje uključen dok ih ne promijenite u **Postavke** → **Općenito** → **Moduli**. Pogledajte [Moduli](#modules).",
  "**Public posts in the Nostr tab**: on the home screen, the Nostr tab shows first **Posts**, the public posts of the people your Nostr key follows and what they shared again, newest first, as in Amethyst or a Telegram channel, with **Chats** one tap away. Older ones come as you scroll to the end, the newest when you pull the list down; tap who wrote a post for their posts or to write to them. Read only, looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Javne objave na kartici Nostr**: na početnom ekranu kartica Nostr prvo prikazuje **Objave**, javne objave ljudi koje prati vaš Nostr ključ i ono što su ponovo podijelili, najnovije prvo, kao u Amethystu ili na Telegram kanalu, a **Razgovori** su jedan dodir dalje. Starije stižu kad se pomaknete do kraja, najnovije kad povučete popis prema dolje; dodirnite onoga tko je napisao objavu za njegove objave ili da mu pišete. Samo za čitanje, traže se preko Tora onako kako određuje prostor i ne čuvaju se, a slike i linkovi se ne otvaraju. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Hidden chats on your linked devices**: each place of hidden chats now links on its own, from inside it, to the same place on a computer or in a browser, with **Linked devices** under its list. Its chats, messages, groups, calls, Chat with myself and its own Matrix, XMPP and Nostr accounts go there, and its contacts write to it there directly. Nothing of it shows in the space or on the space's linked devices. The link runs while the place is open, and while it is closed too with **Receive while closed** on. See [Linked devices](#devices).":
    "**Skriveni razgovori na vašim povezanim uređajima**: svako mjesto skrivenih razgovora sada se povezuje zasebno, iznutra, s istim mjestom na računaru ili u pregledniku, preko **Povezani uređaji** ispod njegovog popisa. Njegovi razgovori, poruke, grupe, pozivi, Razgovor sa sobom i vlastiti Matrix, XMPP i Nostr računi idu tamo, a njegovi kontakti mu tamo pišu direktno. Ništa od toga se ne vidi u prostoru ni na povezanim uređajima prostora. Veza radi dok je mjesto otvoreno, a i zatvoreno ako je uključeno **Primanje dok su zatvoreni**. Pogledajte [Povezani uređaji](#devices).",
  "**Move a chat to another space**: in a chat's **Details**, **Move to another space** takes it, with its messages, name, picture, look and imported chats, into the space whose password you type, as a move into hidden chats does: the safety number stays the same, and their phone is told at once to write there. That space stays closed, and the row shows in every space. A chat never takes the place of one that space, or hidden chats, already have with the same person. See [Second password](#second).":
    "**Premještanje razgovora u drugi prostor**: u **Detalji** razgovora, **Premjesti u drugi prostor** ga nosi, s porukama, imenom, slikom, izgledom i uvezenim razgovorima, u prostor čiju lozinku upišeš, kao premještanje u skrivene razgovore: sigurnosni broj ostaje isti, a telefonu te osobe odmah se javlja da piše tamo. Taj prostor ostaje zatvoren, a stavka se vidi u svakom prostoru. Razgovor nikad ne zauzima mjesto razgovora koji taj prostor, ili skriveni razgovori, već imaju s istom osobom. Vidi [Druga lozinka](#second).",
  // 4.0.0-rc.10
  "**Erevos no longer stops when only the SMS or the Contacts are open**: from them, a contact's chat, an SMS, another icon or a screen that asks for the password again could make Erevos say it could not open (Maximum call stack size exceeded). Now the password opens all of Erevos, then that screen. And when Erevos cannot open, **Try again** starts it again. See [Password lock](#lock).":
    "**Erevos se više ne zaustavlja kada su otvoreni samo SMS-ovi ili kontakti**: odatle su razgovor s kontaktom, SMS, druga ikona ili ekran koji ponovo traži lozinku mogli da dovedu do toga da Erevos kaže da nije mogao da se otvori (Maximum call stack size exceeded). Sada lozinka otvara ceo Erevos, a zatim taj ekran. A kada Erevos ne može da se otvori, **Pokušajte ponovo** ga ponovo pokreće. Pogledajte [Zaključavanje lozinkom](#lock).",
  "**Each icon opens what it names**: after Erevos was opened by the SMS icon, or from the recent apps, another icon, the widget or a notice could sometimes show the SMS instead. Now each opens what it names. With only the SMS or the Contacts open, another icon asks for the password as when Erevos is locked, then opens its own part: the Contacts icon only the contacts, Erevos's own icon all of it. And Back on Erevos's first screen now puts it behind, as Home does, whatever opened it. See [Password lock](#lock).":
    "**Svaka ikona otvara ono što označava**: nakon što je Erevos otvoren ikonom SMS-a ili iz nedavnih aplikacija, druga ikona, widget ili obavijest mogli su ponekad da prikažu SMS-ove umjesto toga. Sada svako otvara ono što označava. Kad su otvoreni samo SMS-ovi ili kontakti, druga ikona traži lozinku kao kad je Erevos zaključan, a zatim otvara svoj dio: ikona Kontakata samo kontakte, sama ikona Erevosa cijeli Erevos. A Nazad na prvom ekranu Erevosa sada ga stavlja u pozadinu, kao dugme za početni ekran, bez obzira na to šta ga je otvorilo. Pogledajte [Zaključavanje lozinkom](#lock).",
  // 4.0.0-rc.9
  "**Only the Contacts**: with Erevos locked, the Contacts icon, the widget's Contacts button and the notice of a birthday ask for the password, then open only the contacts. A chat, an SMS, Settings, and the orange padlock **Unlock everything**, ask for it again, then open all of Erevos. See [Password lock](#lock).":
    "**Samo kontakti**: kad je Erevos zaključan, ikona Kontakata, dugme Kontakti na widgetu i obavijest o rođendanu traže lozinku, a zatim otvaraju samo kontakte. Razgovor, SMS, Postavke i narandžasti lokot **Otključaj sve** ponovo traže lozinku, a zatim otvaraju cijeli Erevos. Pogledajte [Zaključavanje lozinkom](#lock).",
  "**Old private messages in Nostr chats**: Erevos also reads private messages sent the older way (NIP-04), which Damus, Primal and many apps still send and keep, past and new, in the same chats. The relays see who wrote such a message to whom; Erevos itself still sends only the NIP-17 way. See [Chats with other Nostr apps](#nostr-chats).":
    "**Stare privatne poruke u Nostr razgovorima**: Erevos čita i privatne poruke poslane na stariji način (NIP-04), koji Damus, Primal i mnoge aplikacije još koriste i čuvaju: stare i nove, u istim razgovorima. Relayi vide tko je kome napisao takvu poruku; sam Erevos i dalje šalje samo na NIP-17 način. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Public posts in Nostr chats**: in a chat with one person, **Public posts** shows what they post for everyone, newest first, read only. It is looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Javne objave u Nostr razgovorima**: u razgovoru s jednom osobom, **Javne objave** prikazuju ono što ta osoba objavljuje za sve, najnovije prvo, samo za čitanje. Traži se preko Tora onako kako kaže prostor i ne čuva se, a slike i linkovi se ne otvaraju. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  // 4.0.0-rc.8
  // 4.0.0-rc.7
  "**Licence**: Settings → General → Licence says under which licence Erevos is free software, AGPL-3.0-or-later, its three additional terms, that it comes with no warranty, and who made it. See [Licence](#licence).":
    "**Licenca**: Postavke → Općenito → Licenca kaže pod kojom je licencom Erevos slobodan softver, AGPL-3.0-or-later, njegova tri dodatna uslova, da dolazi bez ikakve garancije i ko ga je napravio. Pogledajte [Licenca](#licence).",
  "**Contact**: Settings → General → Contact adds the maker of Erevos as a contact, to write to in Erevos itself, end-to-end encrypted, with no phone number and no email. See [What Erevos is](#about).":
    "**Kontakt**: Postavke → Općenito → Kontakt dodaje autora Erevosa kao kontakt, da mu pišete u samom Erevosu, šifrirano s kraja na kraj, bez broja telefona i bez e-maila. Pogledajte [Šta je Erevos](#about).",
  "**A new sticker set, Angry Eyes**: 24 faces of big yellow eyes on a black disc, drawn by the maintainer, each with the moves he gave it.":
    "**Novi komplet naljepnica, Angry Eyes**: 24 lica s velikim žutim očima na crnom disku, koja je nacrtao autor Erevosa, svako s pokretima koje mu je dao.",
  "**The calculator opens again**: in 4.0.0-rc.6 it closed as soon as it was tapped.":
    "**Kalkulator se ponovo otvara**: u 4.0.0-rc.6 zatvarao se čim biste ga dodirnuli.",
  "**People you follow on Nostr are looked for on more relays**: **Show the people you follow** also asks relays that gather follow lists and more of the relays your key writes on, and waits longer for them; when it finds no one, it says why and how each relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Ljudi koje pratite na Nostru traže se na više relaya**: **Prikaži ljude koje pratite** pita i relaye koji prikupljaju popise praćenih i više relaya na kojima vaš ključ piše, te ih duže čeka; kad nikoga ne nađe, kaže zašto i kako je svaki relay odgovorio. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  // 4.0.0-rc.6
  "**Panic password**: with the password lock on, **Set the panic password** under the Panic button sets a password of its own that, typed on the lock screen, wipes Erevos as **Wipe everything now** does, while the screen shows **Wrong password**. Nothing shows whether one is set. See [Panic button](#panic).":
    "**Lozinka za paniku**: s uključenim zaključavanjem lozinkom, **Postavi lozinku za paniku** u „Gumb za paniku“ postavlja zasebnu lozinku koja, upisana na ekranu za zaključavanje, briše Erevos kao **Obriši sve sada**, dok ekran prikazuje **Pogrešna lozinka**. Ništa ne pokazuje je li neka postavljena. Pogledajte [Gumb za paniku](#panic).",
  "**Calculator in place of Erevos**: on Android, under Launcher icons, a calculator that works can take the place of Erevos's icon; your code, then **=**, opens Erevos, which asks for its password as always. See [Appearance](#appearance).":
    "**Kalkulator umjesto Erevosa**: na Androidu, u „Ikone u pokretaču“, kalkulator koji radi može preuzeti mjesto ikone Erevosa; vaš kod, zatim **=**, otvara Erevos, koji traži svoju lozinku kao uvijek. Pogledajte [Izgled](#appearance).",
  "**Chat with myself on your linked devices too**: notes, photos, files, voice messages and reminders written on one device go to the others, as do a reminder changed or seen and a note deleted. Those from before go once, both ways. See [Linked devices](#devices).":
    "**Razgovor sa sobom i na vašim povezanim uređajima**: bilješke, fotografije, datoteke, glasovne poruke i podsjetnici napisani na jednom uređaju idu na ostale, kao i podsjetnik koji ste promijenili ili vidjeli i bilješka koju ste obrisali. Oni od ranije idu jednom, u oba smjera. Pogledajte [Povezani uređaji](#devices).",
  "**Start when the phone turns on**: on Android, under In the background, Erevos can start by itself after the phone turns on, so the spaces set to say a message came while closed already say \"New message\", never which space or what. Off unless you choose it. See [Chat through a relay](#relay).":
    "**Pokreni kad se telefon uključi**: na Androidu, u „U pozadini“, Erevos se može pokrenuti sam nakon što se telefon uključi, pa prostori postavljeni da kažu da je stigla poruka dok su zatvoreni već kažu „New message“, nikad koji prostor ni što. Isključeno ako ne odaberete. Pogledajte [Razgovor preko relaya](#relay).",
  "**Moving the clock no longer ends the wait after wrong passwords**: it goes by the phone's own time since it started, which no one can set; after a restart it starts again from its beginning. See [Password lock](#lock).":
    "**Pomicanje sata više ne završava čekanje nakon pogrešnih lozinki**: ono ide po vlastitom vremenu telefona otkako se pokrenuo, koje nitko ne može postaviti; nakon ponovnog pokretanja počinje ponovo od početka. Pogledajte [Zaključavanje lozinkom](#lock).",
  "**People you follow on Nostr, found where your other app keeps them**: with a key brought from another Nostr app, **Show the people you follow** also looks on the relays your key writes on, and says so when no relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Ljudi koje pratite na Nostru, nađeni tamo gdje ih drži vaša druga aplikacija**: s ključem donesenim iz druge Nostr aplikacije, **Prikaži ljude koje pratite** traži i na relayima na kojima vaš ključ piše, i kaže kad nijedan relay nije odgovorio. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Your Nostr name keeps the rest of your profile**: saving **Your name** changes only the name in your profile; a picture or words that another app of your key put there stay. Before, they could be wiped. See [Chats with other Nostr apps](#nostr-chats).":
    "**Vaše Nostr ime čuva ostatak vašeg profila**: spremanje u **Vaše ime** mijenja samo ime u vašem profilu; slika ili riječi koje je tamo stavila druga aplikacija vašeg ključa ostaju. Prije su se mogle izbrisati. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Screens come down when no keyboard is open, in every case**: the home screen's list and buttons, or a chat, could still stay up as if a keyboard were open after it had gone. Now Erevos asks Android itself whether a keyboard is shown, and with none they come down within a second.":
    "**Ekrani se spuštaju kad nema otvorene tastature, u svakom slučaju**: lista i dugmad početnog ekrana, ili razgovor, još su mogli ostati gore kao da je tastatura otvorena, nakon što je nestala. Sada Erevos pita sam Android da li se tastatura prikazuje, i bez nje se spuste u roku od jedne sekunde.",
  // 4.0.0-rc.5
  "**New chat opens hidden chats sooner**: hold **New chat** down for a moment, not a whole second, and the field for a PIN of hidden chats opens; on Android the phone buzzes once as it opens. See [Hidden chats](#hidden).":
    "**Novi razgovor brže otvara skrivene razgovore**: zadržite prst na **Novi razgovor** trenutak, ne cijelu sekundu, i otvara se polje za PIN skrivenih razgovora; na Androidu telefon jednom zavibrira kad se otvori. Pogledajte [Skriveni razgovori](#hidden).",
  "**People you follow on Nostr**: under New chat in Nostr chats, **Show the people you follow** lists the people your Nostr key follows, with their names; tap one to write to them. See [Chats with other Nostr apps](#nostr-chats).":
    "**Ljudi koje pratite na Nostru**: u Nostr razgovorima, pod Novi razgovor, **Prikaži ljude koje pratite** navodi ljude koje prati vaš Nostr ključ, s njihovim imenima; dodirnite jednu osobu da joj napišete. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Who makes Erevos, and its licence**: About Erevos now names its maker, and every file of Erevos's source code says whose it is and under which licence; the AGPL-3.0 licence has three added terms (keep the maker's name, mark a changed version, give it another name). See [What Erevos is](#about).":
    "**Ko pravi Erevos, i njegova licenca**: O Erevosu sada kaže ko ga pravi, a svaka datoteka izvornog koda kaže čija je i pod kojom licencom; licenca AGPL-3.0 ima tri dodatna uslova (zadržati ime autora, označiti izmijenjenu verziju kao izmijenjenu i dati joj drugo ime). Vidi [Šta je Erevos](#about).",
  // 4.0.0-rc.4
  "**Numbers on the home chips**: each chip above the chats (All messages, SMS, Erevos, Matrix, XMPP, Nostr) shows how many messages are not read in it, as a small number after its name; muted chats and groups are not counted. See [Getting started](#start).":
    "**Brojevi na dugmadima početnog ekrana**: svako dugme iznad razgovora (Sve poruke, SMS, Erevos, Matrix, XMPP, Nostr) pokazuje koliko u njemu ima nepročitanih poruka, malim brojem iza imena; utišani razgovori i grupe se ne računaju. Pogledajte [Prvi koraci](#start).",
  "**Open a photo full screen in Matrix, XMPP and Nostr chats**: tap a photo shown in a Matrix, XMPP or Nostr chat to see it on the whole screen, with zoom, turning with the phone and Save, as in a chat with a contact. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Fotografija preko cijelog ekrana u Matrix, XMPP i Nostr razgovorima**: dodirnite fotografiju prikazanu u Matrix, XMPP ili Nostr razgovoru da je vidite preko cijelog ekrana, s uvećavanjem, okretanjem s telefonom i dugmetom Sačuvaj, kao u razgovoru s kontaktom. Pogledajte [Matrix](#matrix), [XMPP](#xmpp) i [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Who got and who read your messages in groups**: in a group that is not public, your messages show ✓, then ✓✓ once they reached the phone of every member, and ✓✓✓ once every one read them. Hold one and choose **Who read it** to see who read it and when, whose phone it reached and when, and who has neither yet. A member whose Erevos is older says nothing. A linked computer shows the same marks. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Ko je primio i ko je pročitao vaše poruke u grupama**: u grupi koja nije javna vaše poruke prikazuju ✓, zatim ✓✓ kad su stigle na telefon svakog člana, a ✓✓✓ kad su ih svi pročitali. Zadržite prst na jednoj i izaberite **Ko je pročitao** da vidite ko ju je pročitao i kada, na čiji je telefon stigla i kada, i ko još nije učinio ni jedno ni drugo. Član sa starijim Erevosom ne javlja ništa. Računar povezan s telefonom prikazuje iste oznake. Pogledajte [Razgovor preko relaya](#relay) i [Grupni razgovori](#groups).",
  "**Who read your messages in Matrix**: your messages in a Matrix chat show ✓ once the Matrix server took them and ✓✓✓ once every other member read them, as their Matrix apps tell their servers; **Who read it**, on a message held down, lists who read it and when, and who has not. Matrix has no mark for a message that reached a phone, so there is no ✓✓. See [Matrix](#matrix).":
    "**Ko je pročitao vaše poruke u Matrixu**: vaše poruke u Matrix razgovoru prikazuju ✓ kad ih je preuzeo Matrix server, a ✓✓✓ kad su ih pročitali svi ostali članovi, kako to njihove Matrix aplikacije javljaju njihovim serverima; **Ko je pročitao**, na poruci na kojoj ste zadržali prst, navodi ko ju je pročitao i kada, i ko nije. Matrix nema oznaku za poruku koja je stigla na telefon, pa nema ni ✓✓. Pogledajte [Matrix](#matrix).",
  "**Quiet group messages for the marks**: the group message that says a message came or was read goes only to the senders concerned, and batched; after 300 such messages to some members only, the next goes to all, so no member falls behind in the phone's MLS keys (they accept a jump of 1000 at most). Groups let go of as their space closes send nothing more. See [Group chats](#groups).":
    "**Tihe grupne poruke za oznake**: grupna poruka koja kaže da je poruka stigla ili pročitana ide samo pošiljaocima kojih se tiče, i skupljena; nakon 300 takvih poruka samo nekim članovima, sljedeća ide svima, da nijedan član ne zaostane u MLS ključevima telefona (oni prihvataju skok od najviše 1000). Grupe koje se puste kad se zatvori njihov prostor ne šalju više ništa. Pogledajte [Grupni razgovori](#groups).",
  // 4.0.0-rc.3
  "**Bold, italic, code and hidden words**: in chats and groups, words typed between * become bold, between _ italic, between ~ struck through, between ` code, and between || hidden behind a grey bar until tapped. See [Chat through a relay](#relay).":
    "**Podebljano, kurziv, kôd i skrivene riječi**: u razgovorima i grupama riječi među * postaju podebljane, među _ kurzivne, među ~ precrtane, među ` kôd, a među || skrivene iza sive trake dok ih ne dodirnete. Vidi [Razgovor preko releja](#relay).",
  "**Hidden photo**: under + in a chat or a group, a photo that shows blurred until it is tapped. See [Chat through a relay](#relay).":
    "**Skrivena fotografija**: pod + u razgovoru ili grupi, fotografija koja se prikazuje zamućeno dok je ne dodirnete. Vidi [Razgovor preko releja](#relay).",
  "**Safety message**: under + in a chat, words to a contact that the relay sends by itself if you do not open Erevos for 6 hours to a week; each time you open it, they move on again. See [Chat through a relay](#relay).":
    "**Sigurnosna poruka**: pod + u razgovoru, riječi kontaktu koje relay sam šalje ako ne otvorite Erevos od 6 sati do sedmicu dana; svaki put kad ga otvorite, ponovo se pomjeraju. Vidi [Razgovor preko releja](#relay).",
  "**Name a member in a group with @**: type @ and pick a member; they are told of the message even if they muted the group. See [Group chats](#groups).":
    "**Imenujte člana u grupi sa @**: upišite @ i odaberite člana; dobije obavijest o poruci čak i ako je utišao grupu. Vidi [Grupni razgovori](#groups).",
  "**Reply, change, react and delete in XMPP chats**: hold a message in an XMPP chat or group to answer it, change your words, delete it for everyone or react with an emoji, as Conversations, Dino, Gajim, Monal and Kaidan do; and **typing…** shows while the other person writes. See [XMPP](#xmpp).":
    "**Odgovori, uredi, reaguj i obriši u XMPP razgovorima**: zadržite prst na poruci u XMPP razgovoru ili grupi da na nju odgovorite, promijenite svoje riječi, obrišete je za sve ili reagujete emotikonom, kao što rade Conversations, Dino, Gajim, Monal i Kaidan; a **piše…** se prikaže dok druga osoba piše. Vidi [XMPP](#xmpp).",
  "**See who is writing in a Matrix chat**: **typing…** shows under a Matrix chat while someone writes in it, as the Matrix server says. It shows of you too only if you turn on **Say when I am writing** on the Matrix or XMPP screen: off at first, as it goes through the server not encrypted. See [Matrix](#matrix).":
    "**Vidite ko piše u Matrix razgovoru**: **piše…** se vidi ispod Matrix razgovora dok neko u njemu piše, kako kaže Matrix server. Za vas se vidi samo ako uključite **Reci kad pišem** na ekranu Matrix ili XMPP: isprva isključeno, jer ide preko servera nešifrirano. Pogledajte [Matrix](#matrix).",
  "**Block someone on XMPP**: Block, at the bottom of an XMPP chat, keeps that person's messages, calls and requests from every app of your XMPP account; Unblock lets them through again. See [XMPP](#xmpp).":
    "**Blokirajte nekoga na XMPP-u**: Blokiraj, na dnu XMPP razgovora, drži poruke, pozive i zahtjeve te osobe dalje od svih aplikacija vašeg XMPP računa; Odblokiraj je ponovo propušta. Pogledajte [XMPP](#xmpp).",
  "**Voice messages in XMPP chats**: hold the microphone under an XMPP chat's message box to record, and let go to send; it goes encrypted as the chat is, as Conversations sends one. See [XMPP](#xmpp).":
    "**Glasovne poruke u XMPP razgovorima**: zadržite prst na mikrofonu ispod polja za poruku XMPP razgovora da snimate, i pustite da pošaljete; ide šifrovana kao razgovor, kako je šalje Conversations. Pogledajte [XMPP](#xmpp).",
  "**Matrix groups from Erevos**: New group, on the Matrix screen, makes an encrypted group with a name and the people you invite; Join a group joins one by its address; Invite, in a group, asks someone else in; typing @ in a group names a member, who is told of it. See [Matrix](#matrix).":
    "**Matrix grupe iz Erevosa**: Nova grupa, na Matrix ekranu, pravi šifrovanu grupu s imenom i ljudima koje pozovete; Pridruži se grupi ulazi u grupu po njenoj adresi; Pozovi, u grupi, poziva nekog drugog; kucanjem @ u grupi imenujete člana, kome to stigne kao obavještenje. Pogledajte [Matrix](#matrix).",
  "**The panic button on a computer and on Sailfish OS**: Settings → Privacy and security → Panic button now wipes Erevos there too, with its automatic backups if you choose; on a computer it then starts again as new. See [Panic button](#panic).":
    "**Gumb za paniku na računalu i na Sailfish OS-u**: Postavke → Privatnost i sigurnost → Gumb za paniku sada briše Erevos i ondje, s njegovim automatskim rezervnim kopijama ako to odaberete; na računalu se zatim pokreće kao nov. Pogledajte [Gumb za paniku](#panic).",
  "**Every chat opens at its latest message**: chats with contacts, groups and SMS, and the Matrix, XMPP and Nostr chats, all open at the last message with the message bar under it, and have round arrows to the start, to where you left off (the first message that was new when you opened it) and to the end. See [Getting started](#start).":
    "**Svaki razgovor se otvara na svojoj posljednjoj poruci**: razgovori s kontaktima, grupe i SMS te razgovori preko Matrixa, XMPP-a i Nostra otvaraju se svi na posljednjoj poruci s trakom za poruke ispod, i imaju okrugle strelice na početak, na mjesto gdje je stalo (prva poruka koja je bila nova pri otvaranju) i na kraj. Pogledajte [Prvi koraci](#start).",
  "**The panic button says when it refused**: when your panic app asked to wipe Erevos while the switch was off, or signed with another key, the panic screen now says so, with the time. An app that moves to a new key the way Android allows stays trusted; otherwise you can trust it again as it is now. See [Panic button](#panic).":
    "**Gumb za paniku kaže kad je odbio**: kad je vaša aplikacija za paniku tražila brisanje Erevosa dok je prekidač bio isključen, ili potpisana drugim ključem, zaslon gumba za paniku to sada kaže, s vremenom. Aplikacija koja prelazi na novi ključ na način koji Android dopušta ostaje pouzdana; inače joj možete ponovno vjerovati ovakvoj kakva je sada. Pogledajte [Gumb za paniku](#panic).",
  "**The home screen's chips stay on one line**: with a Nostr, Matrix or XMPP chip as well, **Names** went to a line of its own and the chips moved. Now they stay on one line that slides to the side, and the chosen one is always in sight.":
    "**Dugmad na početnom ekranu ostaju u jednom redu**: kad je tu i dugme Nostr, Matrix ili XMPP, **Imena** su išla u poseban red i dugmad su se pomjerala. Sada ostaju u jednom redu koji možete pomjerati u stranu, a izabrano dugme je uvijek na vidiku.",
  "**Screens come down when the keyboard is gone**: back from another app that had its keyboard open, the home screen's buttons (or a chat's field) could stay up where the keyboard had been, until a keyboard opened again. Now they come down within a second.":
    "**Ekrani se spuštaju kad tastatura nestane**: pri povratku iz druge aplikacije s otvorenom tastaturom, dugmad početnog ekrana (ili polje razgovora) mogla su ostati gore, gdje je bila tastatura, dok se tastatura ponovo ne otvori. Sada se spuste u roku od jedne sekunde.",
  // 4.0.0-rc.2
  "**See what you type in a password or a PIN**: every field for a password, a PIN or a token has an eye at its end: tap it to see what you type, and again to hide it. It is hidden again the next time. See [Password lock](#lock).":
    "**Vidite šta kucate u lozinci ili PIN-u**: svako polje za lozinku, PIN ili token ima oko na kraju: dodirnite ga da vidite šta kucate, i ponovo da se sakrije. Sljedeći put je opet skriveno. Pogledajte [Zaključavanje lozinkom](#lock).",
  "**A chat read as it opens stays read**: messages read while their chat was still opening, as Erevos ended a look at the relay, showed as unread on the home screen once you went back. Now they are marked read as soon as they show.":
    "**Razgovor pročitan dok se otvara ostaje pročitan**: poruke koje si pročitao dok se njihov razgovor još otvarao, dok je Erevos završavao pogled na relay, prikazivale su se kao nepročitane na početnom ekranu čim bi se vratio. Sada su označene kao pročitane čim se pojave.",
  "**Link for a website**: under New chat → Your contact link, a link to put on a web page, such as your contact page. It opens a page that offers Erevos to whoever has none yet, then adds you; what they send comes as a message request. See [Chat through a relay](#relay).":
    "**Link za web stranicu**: u Novi razgovor → Vaš link za kontakt, link koji možete staviti na web stranicu, npr. stranicu za kontakt. Otvara stranicu koja nudi Erevos onome ko ga još nema, a zatim vas dodaje; ono što pošalje stiže kao zahtjev za razgovor. Pogledajte [Razgovor preko relaya](#relay).",
  "**An update's download that stalls is tried again**: when the connection brings nothing for a while, Erevos starts the download again by itself, three times in all, and then says so in its own words. See [Updates](#updates).":
    "**Preuzimanje ažuriranja koje zastane pokušava se ponovo**: kad veza neko vrijeme ne donosi ništa, Erevos sam ponovo počinje preuzimanje, ukupno tri puta, i onda to kaže svojim riječima. Vidi [Ažuriranja](#updates).",
  // 4.0.0-rc.1
  "**Pieces of photos through Nostr stay with their chats**: while a photo that comes through Nostr waits for the rest of its pieces, they are now kept encrypted with the space or the hidden chats they came for, no longer apart where they could be counted, so nothing outside a hidden chats' password says that a photo is on its way to them. Pieces kept before go to the first chats whose photo they are, or after four days. See [Through Nostr](#nostr).":
    "**Komadi fotografija preko Nostra ostaju uz svoje razgovore**: dok fotografija koja stiže preko Nostra čeka ostale svoje komade, oni se sada čuvaju šifrirani s prostorom ili skrivenim razgovorima za koje su stigli, a ne više odvojeno, gdje su se mogli prebrojati, pa ništa izvan lozinke skrivenih razgovora ne govori da im stiže fotografija. Komadi sačuvani ranije idu prvim razgovorima čija su fotografija, ili nestaju nakon četiri dana. Vidi [Preko Nostra](#nostr).",
  "**Encrypted SMS when nothing else works, if you choose**: on Android, when the relay, Nostr, the phones nearby and LoRa all fail, a text to an Erevos contact whose number is linked can go by SMS, end-to-end encrypted, hidden from their SMS app. Off until you turn it on, for all such contacts under Settings → Phone and SMS → SMS, or for one in a chat's Details. It costs SMS (3 for a short text, up to 10 for a longer one), and the phone company sees who wrote to whom, and when. Both phones need Erevos as the SMS app. See [SMS](#sms).":
    "**Šifrirani SMS kad ništa drugo ne radi, ako želite**: na Androidu, kad relay, Nostr, telefoni u blizini i LoRa svi zakažu, tekst Erevos kontaktu s povezanim brojem može ići SMS-om, šifrirano s kraja na kraj i skriveno od njegove SMS aplikacije. Isključeno dok ga ne uključite, za sve takve kontakte pod Postavke → Telefon i SMS → SMS, ili za jedan u Detaljima razgovora. Košta SMS (3 za kratak tekst, do 10 za duži), a mobilni operater vidi ko je kome pisao, i kada. Oba telefona trebaju Erevos kao SMS aplikaciju. Pogledajte [SMS](#sms).",
  "**Answer a hidden call with Answer**: on the \"Incoming call\" screen with no name that a call to your hidden chats brings, **Answer** now asks for the PIN, as the small sign does, and the right PIN answers the call; before, it could not connect, and only the small sign could. See [Hidden chats](#hidden).":
    "**Javite se na skriveni poziv pomoću Javi se**: na ekranu „Dolazni poziv“ bez imena koji donosi poziv vašim skrivenim razgovorima, **Javi se** sada traži PIN, kao i mali znak, a ispravan PIN prima poziv; ranije nije mogao da poveže poziv, a to je mogao samo mali znak. Pogledajte [Skriveni razgovori](#hidden).",
  "**Spam SMS come quietly**: on Android, an SMS that the spam filter's own words catch, a link with words that try to fool from a number that is no contact and that you never answered, still goes to Spam but no longer shows a notice or makes a sound. Spam by your own words and rules still shows one, as they stay encrypted in the space; with the Spam filter off, every SMS does. See [SMS](#sms).":
    "**Spam SMS stižu tiho**: na Androidu, SMS koji uhvate vlastite riječi filtera spama, link s riječima koje pokušavaju prevariti s broja koji nije kontakt i kojem nikad niste odgovorili, i dalje ide u Spam, ali više ne pokazuje obavijest niti zvuči. Spam po vašim riječima i pravilima i dalje je pokazuje, jer one ostaju šifrirane u prostoru; kad je Filter spama isključen, pokazuje je svaki SMS. Pogledajte [SMS](#sms).",
  '**What\'s new in two parts**: each version says first what changes for you, then what changed under the hood: fixes, speed, battery and security inside. See [Updates](#updates).':
    '**Šta je novo, u dva dijela**: svaka verzija prvo kaže šta se mijenja za vas, a zatim šta se promijenilo ispod haube: ispravke, brzina, baterija i sigurnost iznutra. Vidi [Ažuriranja](#updates).',
  '**A contact\'s SMS no longer stay counted as new**: opening their chat reads all of them, the earlier ones too, not only those that show.':
    '**SMS-ovi kontakta više ne ostaju brojani kao novi**: otvaranje njegovog četa čita sve, i ranije, ne samo one koji se vide.',
  '**A message no longer waits when Tor cannot reach the relay**: with Tor for messages, it goes straight at once, as the Tor settings say. See [Through Tor](#tor).':
    '**Poruka više ne čeka kad Tor ne stigne do releja**: s Torom za poruke odmah ide direktno, kako kažu postavke Tora. Vidi [Preko Tora](#tor).',
  '**Background notices no longer stop after a network change**: when the connection of a wait at the relay died on the way (Wi-Fi to mobile data, the relay restarting), Erevos took the relay for one from before, which cannot wait, for the whole run: contacts\' messages then came up to ten minutes late, and hidden chats, closed spaces and hidden rings said nothing until Erevos was restarted. See [Chat through a relay](#relay).':
    '**Obavijesti u pozadini više ne prestaju nakon promjene mreže**: kad bi veza čekanja na relayu umrla usput (s Wi-Fi na mobilne podatke, ponovno pokretanje relaya), Erevos je relay do kraja rada smatrao starim, koji ne zna čekati: poruke kontakata stizale su do deset minuta kasnije, a skriveni razgovori, zatvoreni prostori i skrivena zvonjenja nisu javljali ništa do ponovnog pokretanja Erevosa. Vidi [Razgovor preko relaya](#relay).',
  '**A call hung up at once no longer rings**: when the hang-up came in the same look as the call, the phone rang 45 seconds for a call nobody was on; the same for a group call its starter left at once. See [Chat through a relay](#relay).':
    '**Poziv koji je odmah prekinut više ne zvoni**: kad bi prekid stigao u istom pogledu kao i poziv, telefon je zvonio 45 sekundi za poziv u kojem nije bilo nikoga; isto i za grupni poziv koji je onaj tko ga je započeo odmah napustio. Vidi [Razgovor preko relaya](#relay).',
  '**A hidden call rings once**: a place with Receive while closed and a ring queue rang twice for one call, and a call taken while hidden chats were open rang again as they closed. See [Hidden chats](#hidden).':
    '**Skriveni poziv zvoni jednom**: mjesto s Primanje dok su zatvoreni i redom za zvonjenje zvonilo je dvaput za jedan poziv, a poziv primljen dok su skriveni razgovori bili otvoreni zvonio je ponovno kad su se zatvorili. Vidi [Skriveni razgovori](#hidden).',
  '**A member\'s contact link no longer says New message**: the answer to an ask from a group only adds the contact, with no notice. See [Group chats](#groups).':
    '**Kontaktna poveznica člana više ne javlja Nova poruka**: odgovor na zahtjev iz grupe samo dodaje kontakt, bez obavijesti. Vidi [Grupni razgovori](#groups).',
  '**The birthday notice and the phone\'s incoming call no longer replace each other**: they had the same notice number. See [Contacts](#contacts).':
    '**Obavijest o rođendanu i dolazni poziv telefona više ne zamjenjuju jedno drugo**: imali su isti broj obavijesti. Vidi [Kontakti](#contacts).',
  '**A closed space tells of its contacts\' messages too**: since each contact writes to a queue of their own, a space that says a message came while another is open told only of group messages and first messages from new contacts. It now asks about its contacts\' queues too, up to 64. See [Chat through a relay](#relay).':
    '**Zatvoren prostor javlja i poruke svojih kontakata**: pošto svaki kontakt piše u svoj red, prostor koji javlja da je stigla poruka dok je otvoren drugi javljao je samo poruke grupa i prve poruke novih kontakata. Sada pita i za redove svojih kontakata, do 64. Pogledajte [Razgovor preko relaya](#relay).',
  '**The user guide is in every language of the app**: it shows in the one you chose, and names the buttons as the app shows them. See [Language](#start).':
    '**Korisnički vodič je na svim jezicima aplikacije**: prikazuje se na onom koji ste izabrali i naziva dugmad kako ih aplikacija prikazuje. Vidi [Jezik](#start).',
  '**Location finds where you are, indoors too**: the phone looks by satellite and by its network at once, a sheet says it is looking, and when nothing is found it says why, with Try again. See [Chat through a relay](#relay).':
    '**Lokacija pronalazi gdje ste, i u zatvorenom**: telefon traži preko satelita i preko svoje mreže odjednom, list kaže da traži, a kad ništa ne pronađe kaže zašto, s Pokušajte ponovo. Pogledajte [Razgovor preko relaya](#relay).',
  '**The web app\'s icon counts what is not read**: on an iPhone, with notifications on for the space, Erevos\'s icon on the home screen shows how many messages are not read, never a hidden chat\'s, unless turned off under Settings → Notifications → Number on the icon. See [On an iPhone](#iphone).':
    '**Ikona web-aplikacije broji nepročitano**: na iPhoneu, s uključenim obavijestima za prostor, ikona Erevosa na početnom ekranu pokazuje koliko poruka nije pročitano, nikad iz skrivenog razgovora, osim ako to isključite u „Postavke → Obavijesti → Broj na ikoni“. Vidi [Na iPhoneu](#iphone).',
  "**Notifications for each chat**: on Android, mute a chat or a group for 8 hours, a week or always, and give its messages and its calls a sound of their own, or none. See [Chat through a relay](#relay).":
    "**Obavijesti za svaki razgovor**: na Androidu utišajte razgovor ili grupu na 8 sati, sedmicu ili zauvijek, i dajte njegovim porukama i pozivima vlastiti zvuk, ili nikakav. Pogledajte [Razgovor preko relaya](#relay).",
  "**A chat locked with its own PIN stays locked**: when its contact's Erevos started a new conversation, as it does about once a month, the chat lost its PIN, and a public group joined again lost its own. See [Hidden chats](#hidden).":
    "**Razgovor zaključan vlastitim PIN-om ostaje zaključan**: kad bi Erevos kontakta započeo novi razgovor, što radi otprilike jednom mjesečno, razgovor bi izgubio svoj PIN, a javna grupa u koju si se ponovo pridružio izgubila bi svoj. Vidi [Skriveni razgovori](#hidden).",
  "**Erevos's icon keeps the number of messages not read, on Android**: leaving Erevos with messages not read, a notice without sound keeps how many until you read them, and the launcher shows it on the icon, as a number or a dot. Settings → Notifications → Number on the icon turns it off. See [Chat through a relay](#relay).":
    "**Ikona Erevosa čuva broj nepročitanih poruka, na Androidu**: kad napustite Erevos s nepročitanim porukama, obavijest bez zvuka čuva koliko ih je dok ih ne pročitate, a pokretač je prikazuje na ikoni, kao broj ili tačku. Postavke → Obavijesti → Broj na ikoni to isključuje. Pogledajte [Razgovor preko relaya](#relay).",
  "**The web app's notifications, more dependable**: no New message over Erevos while it is open, and a push held back while the phone was offline no longer counts messages you already read (both with your relay updated), every notice sounds in Chrome, Firefox and Edge, they come back by themselves when the browser changes its push address, and Notifications while closed says when the browser blocks them or your relay was not told yet that they are off. See [On an iPhone](#iphone).":
    '**Obavijesti web-aplikacije, pouzdanije**: nema više „Nova poruka“ preko Erevosa dok je otvoren, a push zadržan dok telefon nije bio na mreži više ne broji poruke koje ste već pročitali (oboje kad je vaš relay ažuriran), svaka obavijest se oglašava zvukom u Chromeu, Firefoxu i Edgeu, same se vraćaju kad preglednik promijeni svoju push adresu, a „Obavijesti dok je Erevos zatvoren“ kažu kad ih preglednik blokira ili kad vašem relayu još nije javljeno da su isključene. Vidi [Na iPhoneu](#iphone).',
  "**Calls ring in the web app, on the computer and on Sailfish OS**: a call that comes while Erevos is open now rings, where only its screen showed, and vibrates where the phone can. On an iPhone it rings once you have touched Erevos, and not on silent. See [On an iPhone](#iphone).":
    "**Pozivi zvone u web-aplikaciji, na računaru i na Sailfish OS-u**: poziv koji stigne dok je Erevos otvoren sada zvoni, gdje se prije pokazivao samo njegov ekran, i vibrira gdje telefon može. Na iPhoneu zvoni kad ste dotakli Erevos, i ne u nečujnom načinu. Vidi [Na iPhoneu](#iphone).",
  '**Erevos on a computer keeps running with its window closed**: in the system tray (on a Mac, in the Dock) it goes on receiving, a call rings and brings the window back, and a notification says how many messages are not read, never who or what. Turn it off under Settings → Notifications → In the background. See [On a computer](#desktop).':
    '**Erevos na računaru radi i dalje sa zatvorenim prozorom**: u sistemskoj traci (na Macu, u Docku) i dalje prima, poziv zvoni i vraća prozor, a obavijest kaže koliko poruka nije pročitano, nikad od koga ni šta. Isključuje se pod Postavke → Obavijesti → U pozadini. Vidi [Na računaru](#desktop).',
  "**Erevos on Sailfish OS tells of messages and calls while it is closed**: while it is out of sight or closed, a small helper waits at the relay for the open space, a notification says how many messages came, never who or what, and a call rings with the phone's ringtone. See [On Sailfish OS](#sailfish).":
    "**Erevos na Sailfish OS-u javlja poruke i pozive dok je zatvoren**: dok nije na ekranu ili je zatvoren, mali pomoćnik čeka na relayu za otvoreni prostor, obavještenje kaže koliko je poruka stiglo, nikad od koga ni šta, a poziv zvoni melodijom telefona. Vidi [Na Sailfish OS-u](#sailfish).",
  "**The relay's pushes to the web app, sturdier**: a push the push service could not take just then is sent again, a call goes before the messages waiting their turn, and whoever runs the relay can allow another push service. Your relay needs an update for it.":
    '**Push od relaya do web-aplikacije, otporniji**: push koji push servis u tom trenutku nije mogao primiti šalje se ponovo, poziv ide prije poruka koje čekaju na red, a onaj ko vodi relay može dozvoliti drugi push servis. Za to je vašem relayu potrebno ažuriranje.',
  "**Permissions checks every notice Erevos uses**: on Android, the message notice without sound or with a chat's own sound, and the reminders', turned off, now show there, with a button to each. See [Chat through a relay](#relay).":
    '**Dozvole provjeravaju svaku obavijest koju Erevos koristi**: na Androidu se tamo sada prikazuju, kad su isključene, i obavijest o porukama bez zvuka ili s vlastitim zvukom razgovora, i obavijest o podsjetnicima, s dugmetom za svaku. Pogledajte [Razgovor preko relaya](#relay).',
  '**Hidden chats say what their switches need**: Say when a message comes and Ring calls when closed say so when Settings → Notifications → In the background lets them do nothing. See [Hidden chats](#hidden).':
    '**Skriveni razgovori kažu šta je potrebno njihovim prekidačima**: „Javi kad stigne poruka“ i „Zvonjava poziva kad su zatvoreni“ to kažu kad im „Postavke → Obavijesti → U pozadini“ ne dozvoljava da išta rade. Pogledajte [Skriveni razgovori](#hidden).',
  "**Truer words about notices**: Settings and the guide give the notices' own words and say what each one needs. See [Chat through a relay](#relay).":
    '**Tačnije riječi o obavijestima**: Postavke i vodič navode vlastite riječi obavijesti i kažu šta je kojoj potrebno. Pogledajte [Razgovor preko relaya](#relay).',
  "**Calls ring as they should**: with Do Not Disturb only when their notice may break through, with a phone's clock off too once the relay is updated, and to the end on Android 7 and 8; a second call is told busy, and a ring stops only for its own call. See [Chat through a relay](#relay).":
    '**Pozivi zvone kako treba**: uz Ne ometaj samo kad njihova obavijest smije proći kroz njega, i kad sat telefona nije tačan, nakon što se relay ažurira, i do kraja na Androidu 7 i 8; drugi poziv dobija odgovor da je zauzeto, a zvonjenje prestaje samo zbog svog poziva. Pogledajte [Razgovor preko relaya](#relay).',
  '**Hidden calls**: one turned down no longer leaves Erevos over the lock screen, one that comes while the password screen shows comes over it, and none rings twice. See [Hidden chats](#hidden).':
    '**Skriveni pozivi**: odbijeni poziv više ne ostavlja Erevos preko zaključanog ekrana, onaj koji stigne dok je prikazan ekran za lozinku prikazuje se preko njega, i nijedan ne zvoni dvaput. Pogledajte [Skriveni razgovori](#hidden).',
  '**Notices come again at once after a change of network**, and receiving starts again as Erevos shows when Android refused it. See [Chat through a relay](#relay).':
    '**Obavijesti ponovo stižu odmah nakon promjene mreže**, a primanje se ponovo pokreće kad se Erevos prikaže, ako ga je Android odbio. Pogledajte [Razgovor preko relaya](#relay).',
  "**Hidden chats' notices tell each message once**: what came since a place last looked is told as it closes, a call that rang is not told again as a message, and a place whose queue the relay lost keeps its switch on. See [Hidden chats](#hidden).":
    '**Obavijesti skrivenih razgovora javljaju svaku poruku jednom**: ono što je stiglo otkako je mjesto zadnji put provjerilo javlja se kad se zatvori, poziv koji je zvonio ne javlja se ponovo kao poruka, a mjesto čiji je red relay izgubio zadržava uključen prekidač. Pogledajte [Skriveni razgovori](#hidden).',
  '**Hidden chats close while Erevos is away**, after 30 seconds, so a call to them meanwhile rings with their PIN to answer. See [Hidden chats](#hidden).':
    '**Skriveni razgovori se zatvaraju dok je Erevos van ekrana**, nakon 30 sekundi, pa poziv za njih u međuvremenu zvoni, a javljate se njihovim PIN-om. Pogledajte [Skriveni razgovori](#hidden).',
  '**A voice message counts once**, on its last part, also when it goes again whole.':
    '**Glasovna poruka se broji jednom**, na svom zadnjem dijelu, i kad ponovo ide cijela.',
  '**The number on the icon counts only what is still there**: a message deleted for everyone, or read on a linked computer, no longer counts. See [Chat through a relay](#relay).':
    '**Broj na ikoni broji samo ono što je još tamo**: poruka obrisana za sve, ili pročitana na povezanom računaru, više se ne broji. Pogledajte [Razgovor preko relaya](#relay).',
  '**Messages sent for later** tell of themselves only while their space is open, without sound if sent so.':
    '**Poruke zakazane za kasnije** javljaju o sebi samo dok je njihov prostor otvoren, bez zvuka ako su tako poslane.',
  '**SMS**: one to the chat on screen only sounds there, they are marked read only while their screen shows, and Android names their notices SMS. See [SMS](#sms).':
    '**SMS**: onaj za razgovor na ekranu oglašava se samo tamo, označavaju se kao pročitani samo dok je njihov ekran prikazan, a Android njihove obavijesti naziva SMS. Pogledajte [SMS](#sms).',
  "**Reminders**: one seen in Chat with myself goes from the notice, a hidden place's go with a new PIN, and birthdays come at 9:00. See [Getting started](#start).":
    '**Podsjetnici**: onaj viđen u Razgovoru sa sobom nestaje iz obavijesti, podsjetnici skrivenog mjesta nestaju s novim PIN-om, a rođendani stižu u 9:00. Pogledajte [Prvi koraci](#start).',
  '**Nostr reads as soon as Tor is ready.** See [Through Nostr](#nostr).':
    '**Nostr čita čim je Tor spreman.** Pogledajte [Preko Nostra](#nostr).',
  "**Erevos's notices show its mark** in the status bar.":
    '**Obavijesti Erevosa prikazuju njegov znak** u statusnoj traci.',
  '**Notices are asked for with receiving off too**, when Say a message came is on.':
    '**Dozvola za obavijesti traži se i s isključenim primanjem**, kad je uključeno „Javi da je stigla poruka“.',
  "**Photos open on the whole screen**: tap one to see it edge to edge, zoom in with two fingers or a double tap, and tap again to hide or show what is around it; big photos open as small ones do. Erevos also turns with the phone while the phone's Auto-rotate is on, and a photo shown on its own even when it is off. See [Chat through a relay](#relay).":
    '**Fotografije se otvaraju preko cijelog ekrana**: dodirnite jednu da je vidite od ivice do ivice, uvećajte je s dva prsta ili dvostrukim dodirom, i dodirnite ponovo da sakrijete ili prikažete ono što je oko nje; velike fotografije se otvaraju kao male. Erevos se i okreće s telefonom dok je na telefonu uključeno Automatsko okretanje, a fotografija prikazana sama i kad je isključeno. Vidi [Razgovor preko relaya](#relay).',
  "**Matrix accounts in Erevos**: sign a space in to Matrix and chat with people who use Element or another Matrix app, end-to-end encrypted, under Settings → Relay and networks → Matrix. These chats are not anonymous, and say so: the Matrix server sees who talks with whom. Text, photos and files. See [Matrix](#matrix).":
    "**Matrix računi u Erevosu**: prijavite prostor na Matrix i razgovarajte s ljudima koji koriste Element ili drugu Matrix aplikaciju, šifrovano s kraja na kraj, u Postavke → Relay i mreže → Matrix. Ovi razgovori nisu anonimni, i to kažu: Matrix server vidi ko s kim razgovara. Tekst, fotografije i datoteke. Pogledajte [Matrix](#matrix).",
  "**Every network's chats on the home screen**: once you sign in to Matrix, its chats are in the list with the Erevos chats and the SMS, newest first, each marked Matrix, and the Matrix chip shows them alone, as SMS and Erevos do. See [Matrix](#matrix).":
    "**Razgovori svih mreža na početnom ekranu**: kad se prijavite na Matrix, njegovi razgovori su na listi s Erevos razgovorima i SMS porukama, najnoviji prvi, svaki označen Matrix, a dugme Matrix pokazuje samo njih, kao SMS i Erevos. Pogledajte [Matrix](#matrix).",
  '**Test versions before a release**: Erevos reads a version such as 4.0.0-rc.1, a test version that comes before 4.0.0, when it looks for updates, tells of a new version and shows what is new. See [Updates](#updates).':
    '**Probne verzije prije izdanja**: Erevos čita verziju poput 4.0.0-rc.1, probnu verziju koja dolazi prije 4.0.0, kad traži ažuriranja, javlja novu verziju i pokazuje šta je novo. Vidi [Ažuriranja](#updates).',
  "**Check Matrix devices by emoji**: in a chat with one person on Matrix, Check by emoji shows you both seven pictures; if they match, nobody sits in between, and Element sees the check too. Check this device with another of yours makes your own Element trust Erevos. See [Matrix](#matrix).":
    "**Provjera Matrix uređaja emojijima**: u razgovoru s jednom osobom na Matrixu, Provjera emojijima vama oboma pokazuje sedam slika; ako se poklapaju, niko nije u sredini, a i Element vidi provjeru. Provjerite ovaj uređaj drugim svojim čini da vaš Element vjeruje Erevosu. Pogledajte [Matrix](#matrix).",
  "**Automatic backups to your own server too**: on Android, each automatic backup can also go to a folder on a server you choose, such as your Nextcloud, over WebDAV. Off until you add one. The server gets random bytes under a random name and cannot open them; it still sees your account, your address and when. See [Backups](#backup).":
    "**Automatske rezervne kopije i na vaš vlastiti server**: na Androidu svaka automatska rezervna kopija može ići i u folder na serveru koji izaberete, kao vaš Nextcloud, preko WebDAV-a. Isključeno dok ne dodate server. Server dobija nasumične bajtove pod nasumičnim imenom i ne može ih otvoriti; ipak vidi vaš nalog, vašu adresu i kada. Pogledajte [Rezervne kopije](#backup).",
  "**Matrix Security Key and key backup**: enter the Security Key Element made, under Settings → Relay and networks → Matrix, and earlier messages open, new keys are backed up, and your other devices trust Erevos. An account with none can set one up there. See [Matrix](#matrix).":
    "**Matrix sigurnosni ključ i rezervna kopija ključeva**: upišite sigurnosni ključ koji je napravio Element, u Postavke → Relay i mreže → Matrix, i ranije poruke se otvaraju, novi ključevi se čuvaju, a vaši drugi uređaji vjeruju Erevosu. Račun bez njega tamo može napraviti jedan. Pogledajte [Matrix](#matrix).",
  "**Matrix through Tor**: on Android, a space's Matrix account follows its choice under Settings → Relay and networks → Tor, so the Matrix server no longer sees where you are; the Matrix screen says when it goes through Tor. See [Matrix](#matrix).":
    "**Matrix preko Tora**: na Androidu, Matrix račun prostora slijedi njegov izbor pod Postavke → Relay i mreže → Tor, pa Matrix server više ne vidi gdje ste; Matrix ekran kaže kada ide preko Tora. Pogledajte [Matrix](#matrix).",
  "**XMPP accounts in Erevos**: sign a space in to XMPP, under Settings → Relay and networks → XMPP, and chat with people who use Conversations, Monal, Gajim, Dino or another XMPP app, encrypted with OMEMO. These chats are not anonymous, and say so: the XMPP server sees who talks with whom. Text with delivery and read marks, photos and files, in the home list under an XMPP chip of its own, and through Tor on Android as you chose. See [XMPP](#xmpp).":
    "**XMPP računi u Erevosu**: prijavite prostor na XMPP, pod Postavke → Relay i mreže → XMPP, i razgovarajte s ljudima koji koriste Conversations, Monal, Gajim, Dino ili drugu XMPP aplikaciju, šifrovano OMEMO-om. Ovi razgovori nisu anonimni i to kažu: XMPP server vidi ko s kim razgovara. Tekst s oznakama isporuke i čitanja, fotografije i datoteke, na listi početnog ekrana pod vlastitim XMPP dugmetom, i preko Tora na Androidu kako ste izabrali. Pogledajte [XMPP](#xmpp).",
  "**Voice and video calls with people on XMPP**: the two tiles at the top of an XMPP chat call the person, and their calls ring on the same screen as Erevos's own, with apps that call as Conversations does. The call goes through your call relay or the XMPP server's, so they do not learn your address; the key that proves it passes through the XMPP servers, which could put themselves in between. See [XMPP](#xmpp).":
    "**Glasovni i video pozivi s ljudima na XMPP-u**: dvije pločice na vrhu XMPP razgovora zovu osobu, a njeni pozivi zvone na istom ekranu kao Erevosovi, s aplikacijama koje zovu kao Conversations. Poziv ide preko vašeg relaya za pozive ili onog XMPP servera, pa ona ne saznaje vašu adresu; ključ koji ga dokazuje ide preko XMPP servera, koji bi se mogli postaviti između. Pogledajte [XMPP](#xmpp).",
  "**Voice and video calls with people on Matrix**: on Android, the two tiles at the top of a Matrix chat call with Element Call, the call app of Element and Element X, which opens inside Erevos in a window of its own, and their calls ring here as Erevos's own do. Sound and picture are end-to-end encrypted and go through the media server your Matrix server names, never through Tor. See [Matrix](#matrix).":
    "**Glasovni i video pozivi s ljudima na Matrixu**: na Androidu, dvije pločice na vrhu Matrix razgovora zovu preko Element Calla, aplikacije za pozive Elementa i Elementa X, koja se otvara u Erevosu u svom prozoru, a njihovi pozivi ovdje zvone kao Erevosovi. Zvuk i slika su šifrovani s kraja na kraj i idu preko medijskog servera koji navodi vaš Matrix server, nikad preko Tora. Pogledajte [Matrix](#matrix).",
  "**Voice and video calls with people on Matrix, in the web app and on a computer**: the two tiles at the top of a Matrix chat call with Element Call there too, as on Android, over the app; its back arrow makes it small in a corner, so you can keep using Erevos during the call. Element Call runs apart from Erevos and can read nothing of it. See [Matrix](#matrix).":
    "**Glasovni i video pozivi s ljudima na Matrixu, u web-aplikaciji i na računaru**: dvije pločice na vrhu Matrix razgovora i tamo zovu preko Element Calla, kao na Androidu, preko aplikacije; strelica nazad u njegovom prozoru smanjuje ga u ugao, pa možete dalje koristiti Erevos tokom poziva. Element Call radi odvojeno od Erevosa i ne može pročitati ništa od njega. Vidi [Matrix](#matrix).",
  "**Chats with people on other Nostr apps**: give a space a Nostr key of its own, under Settings → Relay and networks → Nostr chats, and chat with people who use Damus, Amethyst, Primal, 0xchat or another Nostr app, one to one or in groups, encrypted as NIP-17 asks: the relays see whom a message is for, not who wrote it. These chats are not anonymous, and say so: your key is the same to everyone you write to. Text, photos, files and reactions, in the home list under a Nostr chip of its own, and through Tor on Android as you chose. See [Chats with other Nostr apps](#nostr-chats).":
    "**Razgovori s ljudima u drugim Nostr aplikacijama**: dajte prostoru vlastiti Nostr ključ, pod Postavke → Relay i mreže → Nostr razgovori, i razgovarajte s ljudima koji koriste Damus, Amethyst, Primal, 0xchat ili drugu Nostr aplikaciju, u četiri oka ili u grupama, šifrirano kako traži NIP-17: relayi vide kome je poruka namijenjena, ne i tko ju je napisao. Ovi razgovori nisu anonimni, i to kažu: vaš ključ isti je za sve kojima pišete. Tekst, fotografije, datoteke i reakcije, na popisu početnog ekrana pod vlastitim Nostr dugmetom, i preko Tora na Androidu kako ste odabrali. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Notices for Matrix, XMPP and Nostr messages**: a message in a chat on Matrix, XMPP or Nostr shows a notice and counts in the number on Erevos's icon, as in Erevos's own chats. On Android, Notifications at the bottom of such a chat mutes it or gives it a sound of its own, and an XMPP or Matrix call rings with its chat's ringtone. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Obavijesti za poruke na Matrixu, XMPP-u i Nostru**: poruka u razgovoru na Matrixu, XMPP-u ili Nostru prikazuje obavijest i broji se u broju na ikoni Erevosa, kao u Erevosovim vlastitim razgovorima. Na Androidu, Obavijesti na dnu takvog razgovora ga utišavaju ili mu daju vlastiti zvuk, a XMPP ili Matrix poziv zvoni melodijom svog razgovora. Pogledajte [Matrix](#matrix), [XMPP](#xmpp) i [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**A closed space tells of Matrix messages**: on Android, Say a message came under While this space is closed, on the Matrix screen, has a closed space say \"New message\" when something comes on Matrix while another space is open, never what, from whom or in which chat. Off until you choose it. The Matrix server then tells the space's relay of each message, with no words in it: it learns the relay's address, and the relay when messages come. See [Matrix](#matrix).":
    "**Zatvoren prostor javlja poruke s Matrixa**: na Androidu, „Javi da je stigla poruka“ pod „Dok je ovaj prostor zatvoren“, na ekranu Matrixa, čini da zatvoren prostor kaže „Nova poruka“ kad nešto stigne na Matrixu dok je drugi prostor otvoren, nikad šta, od koga ni u kojem razgovoru. Isključeno dok to ne izabereš. Matrix server tada javlja relayu prostora svaku poruku, bez ijedne njene riječi: saznaje adresu relaya, a relay kad stižu poruke. Vidi [Matrix](#matrix).",
  "**Made with others' open source**: About Erevos, and the guide, now name the open-source projects Erevos is built on, with their makers and their licences. See [What Erevos is](#about).":
    "**Napravljeno uz otvoreni kod drugih**: U O Erevosu i u vodiču sada su navedeni projekti otvorenog koda na kojima je Erevos izgrađen, s njihovim autorima i licencama. Vidi [Šta je Erevos](#about).",
  "**Groups on XMPP**: under Settings → Relay and networks → XMPP, make a private group with your contacts, encrypted with OMEMO for every member as Conversations' private groups are, or join a group by its address, and answer invitations to groups. A group that is not private, a channel, is not encrypted, and says so. Your groups follow your account's other XMPP apps, and a channel tells only of messages that name you. See [XMPP](#xmpp).":
    "**Grupe na XMPP-u**: pod Postavke → Relay i mreže → XMPP, napravite privatnu grupu sa svojim kontaktima, šifrovanu OMEMO-om za svakog člana kao privatne grupe u Conversationsu, ili se pridružite grupi preko njene adrese, i odgovorite na pozive u grupe. Grupa koja nije privatna, kanal, nije šifrovana i to kaže. Vaše grupe prate ostale XMPP aplikacije vašeg računa, a kanal javlja samo za poruke koje vas spominju. Pogledajte [XMPP](#xmpp).",
  "**More in Matrix chats**: hold a message to react to it, reply to it, copy it and, if it is yours, edit it or delete it for everyone. Load earlier messages brings in older ones, and the microphone under the message box sends voice messages that Element plays too. Reactions are not encrypted, as Element sends them. See [Matrix](#matrix).":
    "**Više u Matrix razgovorima**: zadržite poruku da joj reagirate, odgovorite, kopirate je i, ako je vaša, uredite je ili obrišete za sve. „Učitaj ranije poruke“ donosi starije, a mikrofon ispod polja za poruku šalje glasovne poruke koje i Element pušta. Reakcije nisu šifrovane, kako ih šalje Element. Pogledajte [Matrix](#matrix).",
  "**Video added to an XMPP call**: in a voice call with someone on XMPP, either of you can turn on video with Add video; the other is asked first and can say Not now. It works with apps that add video to a call as Conversations does. See [XMPP](#xmpp).":
    "**Video dodan XMPP pozivu**: u glasovnom pozivu s nekim na XMPP-u svako od vas može uključiti video s „Dodaj video“; druga osoba se prvo pita i može reći „Ne sada“. Radi s aplikacijama koje dodaju video pozivu kao Conversations. Pogledajte [XMPP](#xmpp).",
  "**Voice messages and replies in Nostr chats**: hold the microphone under the message box to send a voice message, which plays with Play; hold a message to reply to it, and the answer shows the message it is to, here and in other Nostr apps. See [Chats with other Nostr apps](#nostr-chats).":
    "**Glasovne poruke i odgovori u Nostr razgovorima**: zadržite mikrofon ispod polja za poruku da pošaljete glasovnu poruku, koja se pušta s „Pusti“; zadržite poruku da joj odgovorite, a odgovor prikazuje poruku na koju odgovara, ovdje i u drugim Nostr aplikacijama. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**OMEMO 2 in XMPP chats**: a message to someone whose app speaks OMEMO 2, as Kaidan does, now goes with OMEMO 2 to that app and with OMEMO 0.3 to their others, as before. The XMPP screen shows this device's key both ways, to compare with what each app shows. See [XMPP](#xmpp).":
    "**OMEMO 2 u XMPP razgovorima**: poruka nekome čija aplikacija govori OMEMO 2, kao Kaidan, sada ide s OMEMO 2 toj aplikaciji, a s OMEMO 0.3 njihovim ostalim aplikacijama, kao i prije. XMPP ekran pokazuje ključ ovog uređaja na oba načina, za poređenje s onim što pokazuje svaka aplikacija. Pogledajte [XMPP](#xmpp).",
  "**Hidden chats can have their own Matrix, XMPP and Nostr accounts**: under the list of a place of hidden chats, Matrix, XMPP and Nostr open an account of that place alone, apart from the space's, kept encrypted with the hidden chats' key. Its chats show among the hidden chats only. It connects while they are open, and while they are closed too if Receive while closed is on, as the hidden chats do: then a message says only \"New message\", and a call rings with no name and is answered with the PIN. See [Hidden chats](#hidden).":
    "**Skriveni razgovori mogu imati vlastite Matrix, XMPP i Nostr račune**: ispod popisa mjesta skrivenih razgovora, Matrix, XMPP i Nostr otvaraju račun samo tog mjesta, odvojen od računa prostora i šifrovan ključem skrivenih razgovora. Njegovi razgovori vide se samo među skrivenim razgovorima. Povezuje se dok su otvoreni, a i dok su zatvoreni ako je uključeno Primanje dok su zatvoreni, kao i sami skriveni razgovori: tada poruka kaže samo „Nova poruka“, a poziv zvoni bez imena i javlja se PIN-om. Pogledajte [Skriveni razgovori](#hidden).",
  "**Matrix, XMPP and Nostr in backups**: a backup now holds the Matrix, XMPP and Nostr accounts of every space and of its hidden chats. After a restore, a Nostr key comes back with its chats as they were; an XMPP account goes on as a new device of the account, with its contacts and chats; a Matrix account is let go of on this phone, and the space signs in again as a new device; its Security Key opens the messages from before. See [Backups](#backup).":
    "**Matrix, XMPP i Nostr u rezervnim kopijama**: rezervna kopija sada sadrži Matrix, XMPP i Nostr račune svakog prostora i njegovih skrivenih razgovora. Nakon vraćanja, Nostr ključ se vraća sa svojim razgovorima kakvi su bili; XMPP račun nastavlja kao novi uređaj računa, sa svojim kontaktima i razgovorima; Matrix račun se na ovom telefonu pušta, a prostor se ponovo prijavljuje kao novi uređaj; njegov sigurnosni ključ otvara ranije poruke. Pogledajte [Rezervne kopije](#backup).",
  "**Matrix voice messages show their waveform, and Nostr answers can be photos**: a voice message sent in a Matrix chat carries its waveform, which Element draws, and one that comes with a waveform shows it under Play; in a Nostr chat, a photo, file or voice message sent while a message shows over the message box answers it. See [Matrix](#matrix) and [Chats with other Nostr apps](#nostr-chats).":
    "**Matrix glasovne poruke prikazuju svoj talasni oblik, a Nostr odgovori mogu biti fotografije**: glasovna poruka poslana u Matrix razgovoru nosi svoj talasni oblik, koji Element crta, a ona koja stigne s talasnim oblikom prikazuje ga ispod Pusti; u Nostr razgovoru, fotografija, datoteka ili glasovna poruka poslana dok se poruka prikazuje iznad polja odgovara na nju. Pogledajte [Matrix](#matrix) i [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Group calls in XMPP groups**: in a private XMPP group, start a voice or video call, answer one that rings, or join one going on, together with people who use Dino. See [XMPP](#xmpp).":
    "**Grupni pozivi u XMPP grupama**: u privatnoj XMPP grupi pokrenite glasovni ili video poziv, odgovorite na onaj koji zvoni ili se pridružite onom koji traje, zajedno s ljudima koji koriste Dino. Pogledajte [XMPP](#xmpp).",
  '**A call to a slow phone rings in full**: the caller now waits up to a minute and a quarter for the other phone to say it rings, and then 45 seconds from then, so a call that reached it late no longer rings there only to stop at once; and the phone called reads a call before anything it has to send, and waits for calls again at once after its network changes. See [Chat through a relay](#relay).':
    '**Poziv na spor telefon zvoni do kraja**: onaj ko zove sada čeka do minut i četvrt da drugi telefon kaže da zvoni, a zatim 45 sekundi od tog trenutka, pa poziv koji je tamo stigao kasno više ne zvoni samo da bi odmah stao; a pozvani telefon čita poziv prije svega što ima da pošalje, i odmah ponovo čeka pozive nakon promjene mreže. Vidi [Razgovor preko relaya](#relay).',
  "**The web app and the computer reach Matrix, XMPP and Nostr servers over HTTPS**: their page policy allowed only WebSocket connections, so Matrix sign-in, XMPP server discovery and file sharing, and Nostr files and name lookups failed there. They work now. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Web-aplikacija i računar dopiru do Matrix, XMPP i Nostr servera preko HTTPS-a**: politika njihove stranice dopuštala je samo WebSocket veze, pa tamo nisu radili prijava na Matrix, otkrivanje XMPP servera i dijeljenje datoteka, niti Nostr datoteke i traženje imena. Sada rade. Vidi [Matrix](#matrix), [XMPP](#xmpp) i [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  // 3.4.2
  '**A message sent as a chat opens waits for it**, marked Sending…, and goes as soon as the chat is open, never saying that Erevos cannot encrypt.':
    '**Poruka poslata dok se razgovor otvara čeka ga**, označena Šalje se…, i ide čim se razgovor otvori, bez poruke da Erevos ne može da šifruje.',
  '**What you read as a chat opens stays read**: the home screen no longer counts it as new.':
    '**Ono što pročitaš dok se razgovor otvara ostaje pročitano**: početni ekran ga više ne broji kao novo.',
  '**No question from Samsung about its sharing**: on a Samsung phone, Wi-Fi Aware and the Wi-Fi with phones nearby stay off until you turn them on. See [Chat with a nearby phone](#nearby).':
    '**Samsung više ne pita za svoje deljenje**: na Samsung telefonu Wi-Fi Aware i Wi-Fi mreža s telefonima u blizini ostaju isključeni dok ih ne uključiš. Vidi [Razgovor s telefonom u blizini](#nearby).',
  '**The SMS field keeps its width on a small screen**: Photo and Send beside it are round buttons, as in a chat.':
    '**Polje za SMS zadržava svoju širinu na malom ekranu**: Fotografija i Pošalji pored njega su okrugla dugmad, kao u razgovoru.',
  // 3.4.1
  '**Send answers at once**: a short buzz as you press it, the field empties and the message shows, marked Sending…, so it never goes twice.':
    '**Slanje odgovara odmah**: kratka vibracija kad ga pritisneš, polje se isprazni i poruka se pojavi, označena sa Šalje se…, pa nikad ne ode dvaput.',
  '**The screen no longer stays pushed up** after the keyboard closed behind a sheet, a dialog or another app.':
    '**Ekran više ne ostaje podignut** nakon što se tastatura zatvorila iza prozorčića, dijaloga ili druge aplikacije.',
  '**Importing a chat with its photos no longer freezes Erevos**: the screen moves while the files come in, says what share of them is in, and **Cancel** stops it. A chat moved into hidden chats takes the chats imported into it along. See [Imported chats](#import).':
    '**Uvoz razgovora s njegovim fotografijama više ne zamrzava Erevos**: ekran radi dok datoteke stižu, kaže koliki je dio stigao, a **Otkaži** ga zaustavlja. Razgovor premješten u skrivene razgovore nosi sa sobom razgovore uvezene u njega. Vidi [Uvezeni razgovori](#import).',
  // 3.4.0
  '**Your relay proves its own key**: every connection to it starts with a check only the relay holding that key can pass, so no one in between can pass for it. Once it has, Erevos never reaches it without the check. Your relay needs an update for it.':
    '**Vaš relay dokazuje svoj ključ**: svaka veza s njim počinje provjerom koju može proći samo relay koji ima taj ključ, pa se niko između ne može predstaviti kao on. Kad je jednom prođe, Erevos mu više nikad ne pristupa bez provjere. Za to je vašem relayu potrebno ažuriranje.',
  '[Transparency](#transparency), a new part of the guide: what the server behind Erevos keeps and for how long, what it does not keep, and who else sees something.':
    '[Transparentnost](#transparency), novi dio vodiča: šta server iza Erevosa čuva i koliko dugo, šta ne čuva i ko još nešto vidi.',
  "**What's new**: this list, in Settings → General, by version.": '**Šta je novo**: ovaj popis, po verzijama, u „Postavke → Općenito“.',
  "**Nothing shows behind a chat's PIN**: none of the messages of a chat locked with a PIN is drawn until its PIN is typed, and with glass, a wallpaper or a style's own scene, the PIN screen is a dense frost that lets nothing through.":
    "**Iza PIN-a razgovora ništa se ne vidi**: nijedna poruka razgovora zaključanog PIN-om ne prikazuje se dok se ne upiše njegov PIN, a uz staklo, pozadinu ili stil s vlastitom scenom, ekran PIN-a je gusto mutno staklo kroz koje se ništa ne vidi.",
  "**A group video call from the top of the group**: a blue camera beside the green handset, as in a contact's chat.":
    "**Grupni video poziv s vrha grupe**: plava kamera pored zelene slušalice, kao u razgovoru s kontaktom.",
  "**A relay queue for each contact**: each contact writes to a queue only they know, so the relay cannot tell that two contacts write to the same phone, and deleting or blocking someone deletes only theirs. Your relay needs an update for it.":
    "**Red na releju za svaki kontakt**: svaki kontakt piše u red koji zna samo on, pa relej ne može znati da dva kontakta pišu istom telefonu, a brisanje ili blokiranje nekoga briše samo njegov. Vaš relej za to treba ažuriranje.",
  "**Hidden chats, more like the others**: they close after 30 seconds in the background, not at once, and never during a call or while you pick a photo or a file; while open, a message plays its sound, and link previews have a switch of their own there. See [Hidden chats](#hidden).":
    "**Skriveni razgovori, više kao ostali**: zatvaraju se nakon 30 sekundi u pozadini, ne odmah, i nikad tokom poziva ni dok birate fotografiju ili datoteku; dok su otvoreni, poruka pušta svoj zvuk, a pregledi linkova tamo imaju vlastiti prekidač. Pogledajte [Skriveni razgovori](#hidden).",
  "**Hidden chats that receive while closed**: a switch at the top of each place, on for new places, has them receive as your other chats do: their contacts see at once that a message came, a notice says only \"New message\", and a call rings with no name. See [Hidden chats](#hidden).":
    "**Skriveni razgovori koji primaju dok su zatvoreni**: prekidač na vrhu svakog mesta, uključen za nova mesta, čini da primaju kao vaši ostali razgovori: njihovi kontakti odmah vide da je poruka stigla, obaveštenje kaže samo „Nova poruka“, a poziv zvoni bez imena. Pogledajte [Skriveni razgovori](#hidden).",
  "**Hidden chats wait and import too**: what cannot go now waits, marked Waiting, and goes by itself through their relay; Send later works there as in your other chats; and a chat from Telegram, WhatsApp or Viber can be imported into a hidden chat, kept only there. See [Hidden chats](#hidden).":
    "**Skriveni razgovori takođe čekaju i uvoze**: ono što sada ne može da ode čeka, označeno „Na čekanju“, i šalje se samo preko njihovog relaya; „Pošalji kasnije“ radi tamo kao u vašim ostalim razgovorima; a razgovor iz Telegrama, WhatsAppa ili Vibera može se uvesti u skriveni razgovor i ostati samo tamo. Pogledajte [Skriveni razgovori](#hidden).",
  "**Hidden chats listed like your chats**: they open on a list as the home screen's, with what was said last and how many are not read, and each place has a Chat with myself of its own at its top. See [Hidden chats](#hidden).":
    "**Skriveni razgovori na popisu kao vaši razgovori**: otvaraju se na popisu kao na početnom zaslonu, s onim što je posljednje rečeno i koliko nije pročitano, a svako mjesto ima na vrhu svoj Razgovor sa sobom. Pogledajte [Skriveni razgovori](#hidden).",
  "**More in hidden chats**: with Receive while closed on, what comes to them through Nostr is read while they are closed too; and there a contact can be added from a photo of their QR code, and a hidden contact given a photo. See [Hidden chats](#hidden).":
    "**Više u skrivenim razgovorima**: uz Primanje dok su zatvoreni, ono što im stigne preko Nostra čita se i dok su zatvoreni; a tamo se kontakt može dodati s fotografije njegovog QR koda, a skrivenom kontaktu dati fotografija. Pogledajte [Skriveni razgovori](#hidden).",
  "**Hidden chats with no relay**: as your other chats, they can begin through Nostr only: their contact link and QR code say where they read there, and texts and reactions go there. See [Hidden chats](#hidden).":
    "**Skriveni razgovori bez relaya**: kao vaši drugi razgovori, mogu početi samo preko Nostra: njihov link za kontakt i QR kod kažu gdje tamo čitaju, a tekstovi i reakcije idu tamo. Pogledajte [Skriveni razgovori](#hidden).",
  "**Groups in hidden chats**: under their list, New group makes a group with their contacts; it lists among their chats, goes through their relay only, and is read while they are closed if Receive while closed is on. See [Hidden chats](#hidden).":
    "**Grupe u skrivenim razgovorima**: ispod njihovog popisa, Nova grupa pravi grupu s njihovim kontaktima; ona stoji među njihovim razgovorima, ide samo preko njihovog relaya i čita se dok su zatvoreni ako je Primanje dok su zatvoreni uključeno. Pogledajte [Skriveni razgovori](#hidden).",
  "**No test version line**: the home screen no longer ends saying this is a test version. The guide still says exactly what is protected, and that nothing has been audited yet. See [What is protected today](#privacy).":
    "**Bez retka o probnoj verziji**: početni ekran više ne završava porukom da je ovo probna verzija. Vodič i dalje kaže točno što je zaštićeno i da još ništa nije provjereno. Pogledajte [Što je danas zaštićeno](#privacy).",
  "**The contacts menu in hidden chats**: their Contacts has a menu again, with what is theirs only: a .vcf file imported into them, their contacts saved as a .vcf file, and a contact's QR code read from a photo. An Erevos ID typed there adds them to the hidden chats. See [Contacts](#contacts).":
    "**Meni kontakata u skrivenim razgovorima**: njihovi Kontakti opet imaju meni, samo s onim što je njihovo: uvoz .vcf datoteke u njih, čuvanje njihovih kontakata kao .vcf datoteke i čitanje QR koda kontakta sa fotografije. Erevos ID upisan tamo dodaje osobu u skrivene razgovore. Pogledajte [Kontakti](#contacts).",
  // 3.3.2
  '**The plain call button for more contacts**: the orange keypad at the top of a contact’s chat also takes the number of a contact you connected them to (**Connect to one of my contacts**), the mobile number first.':
    '**Dugme za običan poziv za više kontakata**: narandžasta tastatura na vrhu razgovora s kontaktom uzima i broj kontakta s kojim ste ga povezali (**Poveži s jednim od mojih kontakata**), prvo broj mobilnog.',
  // 3.3.1
  '**Viber chats can be imported**: from the HTML file of the Android app Backup Text for Viber, words only.':
    '**Razgovori iz Vibera mogu se uvesti**: iz HTML datoteke Android aplikacije Backup Text for Viber, samo tekst.',
  // 3.3.0
  '**Start without a relay, through Nostr**: **Start without a relay** on New chat. Texts, stickers, reactions, edits and the delivered and read marks go through Nostr over Tor. Photos, voice messages, files and calls still need a relay or a phone nearby.':
    '**Počnite bez relaya, preko Nostra**: **Počnite bez relaya** u „Novi razgovor“. Tekstovi, naljepnice, reakcije, izmjene i oznake isporučeno i pročitano idu preko Nostra, kroz Tor. Fotografije, glasovne poruke, datoteke i pozivi i dalje trebaju relay ili telefon u blizini.',
  '**The relay comes by itself**: whoever has a relay that invites sends a contact with no relay an invite once, inside the chat, and the other phone takes it by itself.':
    '**Relay stiže sam od sebe**: ko ima relay koji šalje pozivnice, kontaktu bez relaya jednom pošalje pozivnicu, u samom razgovoru, a drugi telefon je sam prihvati.',
  '**Told when a new version is out** (Android): once a day Erevos asks LPHL’s server, then shows a pinned Erevos row and a notice, only for a version the release computer signed. It turns off in Settings → General → Updates.':
    '**Obavijest kad izađe nova verzija** (Android): jednom dnevno Erevos pita LPHL-ov server, pa pokaže prikvačen red Erevos i obavijest, samo za verziju koju je potpisao računar za izdanja. Isključuje se u „Postavke → Općenito → Ažuriranja“.',
  '**Lock a chat with a PIN**: Details → Lock with a PIN, for chats and groups. Nothing of it shows in search, starred messages or imports. In hidden chats it asks for no PIN.':
    '**Zaključajte razgovor PIN-om**: Detalji → Zaključaj PIN-om, za razgovore i grupe. Ništa od njega se ne vidi u pretrazi, porukama sa zvjezdicom ni uvozima. U skrivenim razgovorima PIN se ne traži.',
  '**A new handset** on the green tiles: Phone, and the call in a chat.': '**Nova slušalica** na zelenim pločicama: Telefon i poziv u razgovoru.',
  '**A new New chat screen**: How you connect now at the top, three large cards for a phone without a relay (I have an invite, Sign in with LPHL, Start without a relay), and the technical part under For advanced users.':
    '**Novi ekran „Novi razgovor“**: „Kako ste sada povezani“ na vrhu, tri velike kartice za telefon bez relaya („Imam pozivnicu“, „Prijava preko LPHL“, „Počnite bez relaya“) i tehnički dio pod „Za napredne korisnike“.',
  '**Nostr steadier through Tor**: each Nostr relay has its own way through Tor, and after a failure it tries a new exit. A clearer error on the Nostr screen.':
    '**Stabilniji Nostr preko Tora**: svaki Nostr relay ima vlastiti put kroz Tor, a nakon neuspjeha pokušava novi izlaz. Jasnija greška na ekranu Nostr.',
  '**When the connection to the relay drops** while Erevos waits on it, Erevos notices and connects again, where it stayed stuck before.':
    '**Kad se veza s relayem prekine** dok Erevos čeka na njemu, Erevos to primijeti i ponovo se poveže, a prije bi ostao zaglavljen.',
  '**Invite by SMS** (Android): on a phone contact’s card, for one person, for 2 days. The link opens a page that offers Erevos (the APK for Android, the web app for an iPhone or a computer), then opens the invite. The QR code and Share the invite stay as they were.':
    '**Pozovi putem SMS-a** (Android): na kartici kontakta s telefona, za jednu osobu, na 2 dana. Link otvara stranicu koja nudi Erevos (APK za Android, web-aplikaciju za iPhone ili računar), a zatim otvara pozivnicu. QR kod i „Podijeli pozivnicu“ ostaju kao i prije.',
  '**Fixes to the SMS invite**: a link copied as /i/#… works too, an older web app opens the invite as well, and on iOS 26 it says Share is under •••.':
    '**Ispravke pozivnice putem SMS-a**: radi i link kopiran kao /i/#…, i starija web-aplikacija otvara pozivnicu, a na iOS-u 26 piše da je „Podijeli“ pod •••.',
  '**A phone call button** in Erevos chats and SMS chats.': '**Dugme za telefonski poziv** u Erevos razgovorima i SMS razgovorima.',
  // 3.2.1
  '**Edit a message** you sent, up to a day after: to contacts, groups and linked devices, with Edited beside the time.':
    '**Uredite poruku** koju ste poslali, najkasnije dan poslije: kontaktima, grupama i povezanim uređajima, uz „Uređeno“ pored vremena.',
  '**Nostr says what it did**: Sent through Nostr, and on the Nostr screen what each relay did last.':
    '**Nostr kaže šta je uradio**: „Poslano preko Nostra“, a na ekranu Nostr šta je svaki relay posljednje uradio.',
  '**Coloured call buttons** at the top of a chat: video blue, voice green.': '**Dugmad za pozive u boji** na vrhu razgovora: plavo za videopoziv, zeleno za glasovni.',
  // 3.2.0
  'Arrows to the start and the end of a chat; earlier messages come by themselves as you scroll.':
    'Strelice do početka i kraja razgovora; starije poruke se same učitavaju dok listate.',
  'Chats imported from Telegram and WhatsApp look like Erevos messages: bubbles, days, photos, voice messages, search.':
    'Razgovori uvezeni iz Telegrama i WhatsAppa izgledaju kao Erevos poruke: oblačići, dani, fotografije, glasovne poruke, pretraga.',
  'Dogs instead of cats in the stickers.': 'Psi umjesto mačaka u naljepnicama.',
  'Screenshots: a switch in Settings → Privacy and security.': 'Snimci ekrana: prekidač u „Postavke → Privatnost i sigurnost“.',
  'Hidden chats from New chat: hold it for a second.': 'Skriveni razgovori iz „Novi razgovor“: držite ga jednu sekundu.',
  'Coloured tiles on the home screen: Phone green, Contacts violet, the lock orange.':
    'Pločice u boji na početnom ekranu: zelena za Telefon, ljubičasta za Kontakte, narandžasta za lokot.',
  '**Chat with myself**, always first, and **Remind me**, the orange bell.': '**Razgovor sa sobom**, uvijek prvi, i **Podsjeti me**, narandžasto zvonce.',
  '**Media, links and files** in a chat’s Details, with a calendar and Go to a day.':
    '**Mediji, linkovi i fajlovi** u Detaljima razgovora, s kalendarom i „Idi na dan“.',
  'Import a chat from inside the chat: Details → Imported chats.': 'Uvoz razgovora iz samog razgovora: Detalji → Uvezeni razgovori.',
  'A closed space can say that a message came while another space is open.': 'Zatvoreni prostor može javiti da je stigla poruka dok je otvoren drugi prostor.',
  'The message menu says when a message went or came through Nostr.': 'Meni poruke kaže kad je poruka poslana ili stigla preko Nostra.',
  '**Support Erevos**: Liberapay, PayPal, Monero, Bitcoin.': '**Podržite Erevos**: Liberapay, PayPal, Monero, Bitcoin.',
  'Who makes Erevos and why, in About Erevos; the guide says why everywhere.': 'Ko pravi Erevos i zašto, u „O Erevosu“; vodič svuda objašnjava zašto.',
  // 3.1.2
  '**Settings in 8 groups**, with a search: General, Appearance, Notifications, Privacy and security, Relay and networks, Phone and SMS, Data and devices, For testing. The home screen’s ⋯ keeps only the places, and Settings last.':
    '**Postavke u 8 grupa**, s pretragom: Općenito, Izgled, Obavijesti, Privatnost i sigurnost, Relay i mreže, Telefon i SMS, Podaci i uređaji, Za testiranje. ⋯ na početnom ekranu sadrži samo mjesta, a Postavke su posljednje.',
  // 3.1.1
  'Check for updates says what stopped an update.': '„Provjeri ažuriranja“ kaže šta je spriječilo ažuriranje.',
  'Invite someone is not made from a token for all; it asks you to sign in to the relay first.':
    '„Pozovite nekoga“ se ne pravi iz zajedničkog tokena; prvo traži da se prijavite na relay.',
  'The relay’s token for all becomes a token of the phone’s own, by itself (needs the relay updated).':
    'Zajednički token relaya sam postaje vlastiti token telefona (treba ažuriran relay).',
  'A relay that refuses through Tor says why.': 'Relay koji odbija preko Tora kaže zašto.',
  // 3.1.0
  'Less battery in the background: the relay, Tor and the nearby radios.': 'Manja potrošnja baterije u pozadini: relay, Tor i radio veze u blizini.',
  'Erevos no longer closes when you make a sticker from a photo.': 'Erevos se više ne zatvara kad pravite naljepnicu od fotografije.',
  'Hidden chats’ notices are right.': 'Obavijesti skrivenih razgovora su ispravne.',
  'Hidden chats by holding New chat.': 'Skriveni razgovori držanjem dugmeta „Novi razgovor“.',
  'A search for contacts on the Phone.': 'Pretraga kontakata u Telefonu.',
  'New chat shows first how to add a contact.': '„Novi razgovor“ prvo pokazuje kako dodati kontakt.',
  'A call shows over the screen saver, and the screen wakes.': 'Poziv se prikazuje preko čuvara ekrana, a ekran se budi.',
  'Erevos in other apps’ Share.': 'Erevos u dijeljenju iz drugih aplikacija.',
  'A sound for every new message, also while Erevos shows.': 'Zvuk za svaku novu poruku, i dok je Erevos na ekranu.',
  'The SMS settings say right what holding does.': 'SMS postavke ispravno kažu šta radi zadržavanje prsta.',
  // 3.0.0
  'Each icon opens what it names: Erevos, SMS, Phone, Contacts, the widget.': 'Svaka ikona otvara ono što joj piše: Erevos, SMS, Telefon, Kontakti, widget.',
  '**Messages through Tor by default**: Messages, Everything or Nothing.': '**Poruke preko Tora po zadanom**: Poruke, Sve ili Ništa.',
  '**Texts through Nostr**: three public relays, through Tor, with your own relay as backup after 5 minutes.':
    '**Tekstovi preko Nostra**: tri javna relaya, kroz Tor, s vašim vlastitim relayem kao rezervom nakon 5 minuta.',
  // 2.0.3
  'One invite for everything: the relay and the contact together.': 'Jedna pozivnica za sve: relay i kontakt zajedno.',
  'Spam rules for senders and numbers abroad, with the reason.': 'Pravila za spam za pošiljaoce i brojeve iz inostranstva, s razlogom.',
  '480 stickers in 20 sets.': '480 naljepnica u 20 paketa.',
  'Lighter chats on older phones; QR codes at once.': 'Lakši razgovori na starijim telefonima; QR kodovi odmah.',
  'Copy code for one-time codes in SMS.': '„Kopiraj kod“ za jednokratne kodove u SMS porukama.',
  'Locked, Erevos keeps receiving.': 'I zaključan, Erevos i dalje prima poruke.',
  'Faster contacts; the hidden chats’ notice counts only messages.': 'Brži kontakti; obavijest skrivenih razgovora broji samo poruke.',
  'The relay tries every address: push, other relays, the LPHL sign-in.': 'Relay pokušava svaku adresu: push, druge relaye, prijavu preko LPHL-a.',
  // 2.0.2
  'Swiping on the tabs only changes the tab.': 'Prevlačenje po karticama samo mijenja karticu.',
  'The icons fill the launcher’s shape.': 'Ikone popunjavaju oblik pokretača.',
  // 2.0.1
  'Coloured icons (Erevos red, Phone green, SMS blue, Contacts violet) and a new SMS icon.':
    'Ikone u boji (Erevos crvena, Telefon zelena, SMS plava, Kontakti ljubičasta) i nova SMS ikona.',
  'A colour for each icon, and the order of the widget’s buttons.': 'Boja za svaku ikonu i redoslijed dugmadi widgeta.',
  'Swipe to go back, and between tabs.': 'Prevlačenje za povratak i između kartica.',
  // 2.0.0
  'An update of the WebView no longer closes Erevos.': 'Ažuriranje komponente WebView više ne zatvara Erevos.',
  'Deleting or blocking a contact gives you a new queue on the relay.': 'Brisanje ili blokiranje kontakta daje vam novi red na relayu.',
  'A new contact can take the name of a contact on the phone.': 'Novi kontakt može preuzeti ime kontakta s telefona.',
  '**Sign in to the relay with LPHL**, and **invites to the relay**.': '**Prijava na relay preko LPHL-a** i **pozivnice na relay**.',
  'Permissions in the web app, and more on Android; the web app’s notice says how many came.':
    'Dozvole u web-aplikaciji, i više njih na Androidu; obavijest web-aplikacije kaže koliko ih je stiglo.',
  'Hidden chats can ring calls while they are closed.': 'Skriveni razgovori mogu zvoniti na pozive dok su zatvoreni.',
  'New keys every month in chats, every week in groups.': 'Novi ključevi svaki mjesec u razgovorima, svake sedmice u grupama.',
  'Linked devices work with the phone off.': 'Povezani uređaji rade i kad je telefon isključen.',
  'A new chat screen; QR codes from a photo; the Phone for small screens.': 'Novi ekran razgovora; QR kodovi s fotografije; Telefon za male ekrane.',
  'Add as contact inside a group.': '„Dodaj u kontakte“ unutar grupe.',
  'Stickers in sets, moving, and your own.': 'Naljepnice u paketima, pokretne i vlastite.',
  'SMS inside the Erevos chat.': 'SMS unutar Erevos razgovora.',
  'Android updates need the release computer’s signature.': 'Ažuriranja za Android trebaju potpis računara za izdanja.',
  'An F-Droid build; Serbo-Croatian; new version numbers.': 'Verzija za F-Droid; srpskohrvatski; novi brojevi verzija.',
  'Much for security: Argon2id, messages encrypted for the relay too, a token for each phone, no link starts a call.':
    'Mnogo toga za sigurnost: Argon2id, poruke šifrirane i za relay, token za svaki telefon, nijedan link ne pokreće poziv.',
  // 0.1.16
  'Imports from Telegram and WhatsApp bring photos, videos, voice messages and files.': 'Uvozi iz Telegrama i WhatsAppa donose fotografije, videozapise, glasovne poruke i datoteke.',
  'A phone without a relay talks through a place on a contact’s relay.': 'Telefon bez relaya razgovara preko mjesta na relayu kontakta.',
  // 0.1.14
  'Back to my chats, for hidden chats.': '„Vrati u moje razgovore“, za skrivene razgovore.',
  'Erevos receives and rings even after you swipe it away from the recent apps.': 'Erevos prima poruke i zvoni i kad ga prevučete iz nedavnih aplikacija.',
  // 0.1.12
  'Hidden chats can say a message came.': 'Skriveni razgovori mogu javiti da je stigla poruka.',
  'Fixes: menus, QR codes from a photo, Bluetooth on Android 17, long lists.': 'Ispravke: meniji, QR kodovi s fotografije, Bluetooth na Androidu 17, dugi popisi.',
  // 0.1.11
  'The Phone without the password, if you allow it; a home screen widget; an SMS and Erevos filter.':
    'Telefon bez lozinke, ako to dozvolite; widget za početni ekran; filter za SMS i Erevos.',
  // 0.1.10
  'Links wait for the password; Phone and Contacts icons; the Erevos ID on a contact.': 'Linkovi čekaju lozinku; ikone Telefona i Kontakata; Erevos ID na kontaktu.',
  // 0.1.8
  '61 new features: 5 new languages, linked devices, public groups, replies, reactions, polls, send later, Erevos as the phone and contacts app, Tor bridges, the fingerprint, Windows and more.':
    '61 nova mogućnost: 5 novih jezika, povezani uređaji, javne grupe, odgovori, reakcije, ankete, kasnije slanje, Erevos kao aplikacija za telefon i kontakte, Tor mostovi, otisak prsta, Windows i još mnogo toga.',
  // 0.1.7 to 0.1.2
  'SMS notices in the background.': 'SMS obavijesti u pozadini.',
  'The web app comes out with every release.': 'Web-aplikacija izlazi sa svakim izdanjem.',
  'Greek in the whole app.': 'Grčki u cijeloj aplikaciji.',
  'Web Push in the web app.': 'Web Push u web-aplikaciji.',
  'The first signed Android release: encrypted chats, calls, groups, hidden chats, backups, imports, and phones nearby without the internet.':
    'Prvo potpisano izdanje za Android: šifrirani razgovori, pozivi, grupe, skriveni razgovori, rezervne kopije, uvozi i telefoni u blizini bez interneta.',
  "**Two new sticker sets of 24 moods**: **Tux**, the Linux penguin as he is drawn, and **Aikido**, an aikidoka in keikogi and a wide hakama, who also bows, sits in seiza and rolls.":
    "**Dva nova kompleta naljepnica s 24 raspoloženja**: **Tux**, Linuxov pingvin kakav je nacrtan, i **Aikido**, aikidoka u keikogiju i širokoj hakami, koji se i klanja, sjedi u seizi i kotrlja se.",
  "**A new sticker set, Takis**: a caricature in a dark suit and a purple tie with dots, in 24 moods that move.":
    "**Novi komplet naljepnica, Takis**: karikatura u tamnom odijelu i ljubičastoj kravati s točkicama, u 24 raspoloženja koja se miču.",
  "**Photos, files and voice messages with no relay**: when there is no relay between you and your contact and they read on Nostr, a voice message goes through Nostr like a text, a photo up to 3 MB in pieces, and a larger photo, a video or another file, up to 20 MB, to an encrypted file server (Blossom), all through Tor. See [Through Nostr](#nostr).":
    "**Fotografije, datoteke i glasovne poruke bez relaya**: kad između vas i vašeg kontakta nema relaya, a on čita na Nostru, glasovna poruka ide preko Nostra kao tekst, fotografija do 3 MB u komadima, a veća fotografija, video ili druga datoteka, do 20 MB, na šifrirani poslužitelj datoteka (Blossom), sve preko Tora. Pogledajte [Preko Nostra](#nostr).",
  "**More battery saved in the background, if you choose**: under Settings → Notifications → In the background, Only the waste stays the default; And nearby phones also turns off the radios for phones nearby while Erevos is in the background; And sleep also lets the phone sleep, so Erevos looks at your relay about once a minute and a message or a call can be a minute or two late. Android only. See [Chat through a relay](#relay).":
    "**Više uštede baterije u pozadini, ako to odaberete**: u Postavke → Obavijesti → U pozadini, Samo rasipanje ostaje zadano; I telefoni u blizini isključuje i radije za telefone u blizini dok je Erevos u pozadini; I san dopušta i telefonu da spava, pa Erevos gleda vaš relay otprilike jednom u minuti, a poruka ili poziv mogu kasniti minutu-dvije. Samo Android. Pogledajte [Razgovor preko relaya](#relay).",
  "**A contact you delete no longer comes back from an old ask**: in a group, a member you asked for their contact link, or who asked for yours, and whom you then deleted as a contact before Erevos looked at the relay again, could be added again by that old ask. Deleting them now lets go of it at once. See [Group chats](#groups).":
    "**Obrisan kontakt se više ne vraća starim zahtjevom**: u grupi je član čiji ste kontakt-link tražili, ili koji je tražio vaš, a kojeg ste zatim obrisali kao kontakt prije nego što je Erevos opet pogledao relay, mogao biti ponovo dodan tim starim zahtjevom. Sada ga brisanje odmah ispušta. Pogledajte [Grupni razgovori](#groups).",
  "**Every message says which way it went**: hold a message and its menu says whether it went or came through the relay, through Nostr, to a phone nearby or over LoRa. Messages from before say nothing. See [Through Nostr](#nostr).":
    "**Svaka poruka kaže kojim je putem išla**: zadržite prst na poruci i njen meni kaže je li otišla ili stigla preko relaya, preko Nostra, preko obližnjeg telefona ili preko LoRa. Starije poruke ne kažu ništa. Pogledajte [Preko Nostra](#nostr).",
  "**The spam filter reads words as they look**: a scam text that swaps a letter for a look-alike of another alphabet, or hides a mark that shows nothing inside a word, no longer gets past it. See [SMS](#sms).":
    "**Filter za spam čita riječi kako izgledaju**: prevarantska SMS poruka koja zamijeni slovo sličnim slovom iz drugog pisma, ili u riječ sakrije znak koji se ne vidi, više ga ne zavarava. Pogledajte [SMS](#sms).",
  "**Media, links and files in groups too**: in a group's details, a list of its photos, videos, voice messages, music, files and links, each kind apart under its months, with a calendar, as in a contact's chat. A tap opens or plays; held, each goes to its message. See [Group chats](#groups).":
    "**Mediji, linkovi i fajlovi i u grupama**: u detaljima grupe popis njenih fotografija, videa, glasovnih poruka, muzike, fajlova i linkova, svaka vrsta posebno pod svojim mjesecima, s kalendarom, kao u razgovoru s kontaktom. Dodir otvara ili pušta; držanjem svaki ide na svoju poruku. Pogledajte [Grupni razgovori](#groups).",
  "**A relay restart no longer brings a false notice**: after your relay restarted, a hidden chat or a closed space said New message once more for messages it had told of already. Your relay needs an update for it. See [Hidden chats](#hidden).":
    "**Ponovno pokretanje relaya više ne donosi lažno obavještenje**: nakon što bi se vaš relay ponovo pokrenuo, skriveni razgovor ili zatvoren prostor opet bi rekao Nova poruka za poruke koje je već javio. Za to je vašem relayu potrebno ažuriranje. Pogledajte [Skriveni razgovori](#hidden).",
  "**Backups to your server through Tor**: on Android, automatic backups sent to your own server now follow the space's choice under Settings → Relay and networks → Tor, as Matrix does, so with Tor the server no longer sees where you are. To a server too says when they go through Tor. See [Backups](#backup).":
    "**Rezervne kopije na vaš server preko Tora**: na Androidu automatske rezervne kopije koje idu na vaš server sada slijede izbor prostora pod Postavke → Relay i mreže → Tor, kao Matrix, pa uz Tor server više ne vidi gdje ste. I na server kaže kad idu preko Tora. Pogledajte [Rezervne kopije](#backup).",
  "**Restore a backup straight from your server**: Restore from a server, under Backups, lists the backups on your server, newest first, and opens the one you choose with its password, with no download by hand, on a new phone too. See [Backups](#backup).":
    "**Vratite rezervnu kopiju direktno sa svog servera**: Vrati sa servera, pod Rezervne kopije, prikazuje rezervne kopije na vašem serveru, najnovije prve, i otvara onu koju izaberete njenom lozinkom, bez ručnog preuzimanja, i na novom telefonu. Pogledajte [Rezervne kopije](#backup).",
  "**Backups to your server from a computer and the web app too**: in the desktop app, automatic backups go to your WebDAV server as on Android; in the web app, Send a backup now sends one there, with a server that lets the web app in. Both can restore from it. Not through Tor. See [Backups](#backup).":
    "**Rezervne kopije na vaš server i s računara i iz web aplikacije**: u aplikaciji za računar automatske rezervne kopije idu na vaš WebDAV server kao na Androidu; u web aplikaciji Pošalji rezervnu kopiju sada šalje jednu tamo, uz server koji pušta web aplikaciju. Obje mogu vratiti s njega. Ne preko Tora. Pogledajte [Rezervne kopije](#backup).",
  "**Check a contact in person with QR codes**: under Safety number in a chat's details, each phone shows a code; take a photo of the code on the other phone, and they of yours. When it matches, the contact is marked Checked in person. Nothing is sent. See [Chat through a relay](#relay).": "**Provjerite kontakt uživo QR kodovima**: pod Sigurnosni broj, u detaljima razgovora, svaki telefon prikazuje kod; fotografirajte kod na drugom telefonu, a ta osoba vaš. Kad se podudara, kontakt se označi kao Provjereno uživo. Ništa se ne šalje. Pogledajte [Razgovor preko relaya](#relay).",
  "**Up to three home relays**: under Settings → Relay and networks → Home relay, Add another home relay gives a space up to two more, each with a queue of its own. Your contact link and your messages name them in order, and contacts try each while the ones before cannot be reached. See [Home relay](#home-relay).": "**Do tri kućna relaya**: pod Postavke → Relay i mreže → Kućni relay, Dodajte još jedan kućni relay daje prostoru do još dva, svaki s vlastitim redom. Vaš link za kontakt i vaše poruke navode ih redom, a kontakti probaju svaki dok prethodni nisu dostupni. Pogledajte [Kućni relay](#home-relay).",
  "**Introduce two of your contacts**: in a contact's chat details, Introduce to a contact asks them and another contact of yours, each in your chat with them. Only if both say yes do they become contacts, and neither learns whether the other said no. See [Chat through a relay](#relay).": "**Upoznajte dva svoja kontakta**: u detaljima razgovora s kontaktom, Upoznajte s kontaktom pita njega i još jedan vaš kontakt, svakog u vašem razgovoru s njim. Postaju kontakti samo ako oboje kažu da, a niko ne saznaje je li drugi rekao ne. Pogledajte [Razgovor preko relaya](#relay).",
  "**Bluetooth that cannot be followed**: the random number your phone sends out over Bluetooth for phones nearby to find it changed only when Erevos started again; it now changes every nine to twelve minutes, so someone listening cannot follow your phone from place to place by it. Older Erevos phones still find yours. See [Chat with a nearby phone](#nearby).": "**Bluetooth koji se ne može pratiti**: slučajni broj koji vaš telefon šalje preko Bluetootha da bi ga telefoni u blizini našli mijenjao se samo kad bi se Erevos ponovo pokrenuo; sada se mijenja svakih devet do dvanaest minuta, pa neko ko sluša ne može po njemu pratiti vaš telefon od mjesta do mjesta. Telefoni sa starijim Erevosom i dalje nalaze vaš. Pogledajte [Razgovor s telefonom u blizini](#nearby).",
  "**Hidden chats show at once**: as the PIN opens them, their chats and contacts show at once, to read, while what they were receiving in the background ends; before, that could hold them back a long while, as it may go through Tor. See [Hidden chats](#hidden).": "**Skriveni razgovori se vide odmah**: čim ih PIN otvori, njihovi razgovori i kontakti se vide odmah, za čitanje, dok se ono što su primali u pozadini završava; ranije ih je to moglo dugo zadržavati, jer može ići preko Tora. Pogledajte [Skriveni razgovori](#hidden).",
  "**Your backup password in pieces with friends**: under Settings → Data and devices → Backup pieces, give pieces of it to 3 to 5 contacts; any 2 or 3 of them give it back, one alone shows nothing. Each goes inside the encryption of your chat with them and only their Erevos keeps it; your phone keeps none. See [Backup pieces with friends](#backup-pieces).": "**Lozinka rezervnih kopija u dijelovima kod prijatelja**: pod Postavke → Podaci i uređaji → Dijelovi rezervne kopije dajte njene dijelove 3 do 5 kontakata; bilo koja 2 ili 3 je vraćaju, jedan sam ne pokazuje ništa. Svaki ide unutar šifriranja vašeg razgovora s njima i čuva ga samo njihov Erevos; vaš telefon ne čuva nijedan. Pogledajte [Dijelovi rezervne kopije kod prijatelja](#backup-pieces).",
  "**Panic button**: under Settings → Privacy and security → Panic button, wipe everything Erevos keeps here with one tap, on Android and in the web app. On Android, a panic app such as Ripple can do it too, but only the one you say yes to, checked by its signature. See [Panic button](#panic).": "**Gumb za paniku**: pod Postavke → Privatnost i sigurnost → Gumb za paniku jednim dodirom obrišite sve što Erevos ovdje čuva, na Androidu i u web aplikaciji. Na Androidu to može i aplikacija za paniku poput Ripplea, ali samo ona kojoj kažete da, provjerena po svom potpisu. Pogledajte [Gumb za paniku](#panic).",
  "**Erevos to a phone nearby, with no internet**: under Settings → General → Give Erevos to a phone nearby, this phone serves its Erevos over the same Wi-Fi or its hotspot for ten minutes, with a QR code. A phone without Erevos downloads it in the browser; one with an older Erevos takes it under Updates → From a phone nearby, which installs it only when it is Erevos, signed as that one is. See [Erevos to a phone nearby](#give-app).": "**Erevos obližnjem telefonu, bez interneta**: pod Postavke → Općenito → Daj Erevos obližnjem telefonu ovaj telefon deset minuta poslužuje svoj Erevos preko iste Wi-Fi mreže ili svog hotspota, s QR kodom. Telefon bez Erevosa preuzima ga u pregledniku; onaj sa starijim Erevosom uzima ga pod Ažuriranja → S obližnjeg telefona, koje ga instalira samo ako je to Erevos, potpisan kao taj. Pogledajte [Erevos obližnjem telefonu](#give-app).",
  "**Hidden chats with phones nearby**: while hidden chats are open, or receive while closed, they reach a contact's phone nearby over Bluetooth, Wi-Fi Aware, Wi-Fi Direct or the same Wi-Fi, with no internet, as your other chats do. The space never learns that a hidden contact is near, and nothing on the air tells their messages from the space's; other phones never carry them, and they never go over LoRa or by SMS. See [Hidden chats](#hidden).":
    "**Skriveni razgovori s telefonima u blizini**: dok su skriveni razgovori otvoreni, ili primaju i zatvoreni, stižu do telefona kontakta u blizini preko Bluetootha, Wi-Fi Awarea, Wi-Fi Directa ili na istoj Wi-Fi mreži, bez interneta, kao vaši ostali razgovori. Prostor nikad ne sazna da je skriveni kontakt u blizini, i ništa u eteru ne razlikuje njihove poruke od poruka prostora; drugi telefoni ih nikad ne nose, i nikad ne idu preko LoRa ni SMS-om. Pogledajte [Skriveni razgovori](#hidden).",
  "**The same Wi-Fi on Sailfish OS**: Erevos on Sailfish OS finds Erevos phones and computers on the same Wi-Fi or a phone's hotspot and talks with them with no internet, as on a computer. See [On Sailfish OS](#sailfish).":
    "**Ista Wi-Fi mreža na Sailfish OS-u**: Erevos na Sailfish OS-u pronalazi telefone i računare s Erevosom na istoj Wi-Fi mreži ili hotspotu telefona i razgovara s njima bez interneta, kao na računaru. Pogledajte [Na Sailfish OS-u](#sailfish).",
  "**Downloads stop at 100 MB**: a file, a backup from a server or any other download is read as it comes and stopped as soon as it passes 100 MB, or less where the network's files are smaller, such as 20 MB for Nostr files, so a file server a contact names can no longer fill the phone's memory with an answer without end. A backup on a server comes back up to 100 MB; download a larger one and open it with Restore a backup. See [Backups](#backup).":
    "**Preuzimanja staju na 100 MB**: datoteka, rezervna kopija sa servera ili bilo koje drugo preuzimanje čita se kako stiže i zaustavlja čim pređe 100 MB, ili manje gdje su datoteke mreže manje, kao 20 MB za Nostr datoteke, pa server datoteka koji kontakt navede više ne može napuniti memoriju telefona odgovorom bez kraja. Rezervna kopija na serveru vraća se do 100 MB; veću preuzmite i otvorite je sa Vrati rezervnu kopiju. Pogledajte [Rezervne kopije](#backup).",
  "**Profile pictures on Matrix and XMPP**: contacts and Matrix rooms show their picture in the chat list, and you can set your own on the Matrix and XMPP screens (Choose a photo). Pictures are not encrypted on either network: the server sees them. See [Matrix](#matrix) and [XMPP](#xmpp).":
    "**Profilne slike na Matrixu i XMPP-u**: kontakti i Matrix sobe prikazuju svoju sliku na popisu razgovora, a svoju možete postaviti na ekranima Matrix i XMPP (Odaberi fotografiju). Slike nisu šifrirane ni na jednoj mreži: server ih vidi. Pogledajte [Matrix](#matrix) i [XMPP](#xmpp).",
  "**Run an XMPP group**: a group's admins can set its subject and take people out or bar them, its owner can rename it and make admins, and in a channel the admin sees who is in it and can put them out. See [XMPP](#xmpp).":
    "**Upravljanje XMPP grupom**: admini grupe postavljaju njenu temu i uklanjaju ili zabranjuju ljude, vlasnik je preimenuje i postavlja admine, a u kanalu admin vidi ko je unutra i može ga izbaciti. Pogledajte [XMPP](#xmpp).",
  "**Check a Matrix device by QR code**: once both sides accept a check, Erevos shows a code for Element (or another Erevos) to photograph, or photographs theirs, as Element does; comparing emoji stays one tap away. See [Matrix](#matrix).":
    "**Provjera Matrix uređaja QR kodom**: kad obje strane prihvate provjeru, Erevos pokazuje kod koji Element (ili drugi Erevos) fotografiše, ili fotografiše njihov, kao Element; poređenje emojija ostaje na jedan dodir. Pogledajte [Matrix](#matrix).",
  "**Sign in to Matrix with single sign-on** (Android): when your Matrix server signs people in on its own page, as matrix.org does, Sign in with single sign-on opens it in the browser and comes back to Erevos. See [Matrix](#matrix).":
    "**Prijava na Matrix jedinstvenom prijavom** (Android): kad tvoj Matrix server prijavljuje ljude na svojoj stranici, kao matrix.org, „Prijava jedinstvenom prijavom (SSO)” otvara je u pregledniku i vraća se u Erevos. Vidi [Matrix](#matrix).",
  "**A closed space tells of XMPP messages**: on Android, Say a message came under While this space is closed, on the XMPP screen, has a closed space say \"New message\" when something comes on XMPP while another space is open, never what, from whom or in which chat. Off until you choose it. It needs a relay updated for it and an XMPP server that sends notices to apps that are away; the XMPP server then learns the relay's name, and the relay when messages come. See [XMPP](#xmpp).":
    "**Zatvoren prostor javlja o XMPP porukama**: na Androidu, „Javi da je stigla poruka“ pod „Dok je ovaj prostor zatvoren“ na ekranu XMPP-a pušta zatvoren prostor da kaže „Nova poruka“ kad nešto stigne na XMPP-u dok je otvoren drugi prostor, nikad šta, od koga ni u kojem razgovoru. Isključeno dok ne izaberete. Treba relay ažuriran za to i XMPP server koji šalje obavijesti neaktivnim aplikacijama; XMPP server tada saznaje ime relaya, a relay kad stižu poruke. Vidi [XMPP](#xmpp).",
  "**Linking a computer is clearer**: on a computer, Settings → Data and devices → Linked devices now starts with Link to my phone, with LPHL's relay filled in and Sign in with LPHL under the token, so no token has to be copied from the phone; and it says that the QR code shows once Link to my phone is tapped. See [Linked devices](#devices).":
    "**Povezivanje računara je jasnije**: na računaru Postavke → Podaci i uređaji → Povezani uređaji sada počinju s „Poveži s mojim telefonom“, s već upisanim LPHL-ovim relayom i „Prijava preko LPHL“ ispod tokena, pa nijedan token ne treba kopirati s telefona; i kaže da se QR kod prikazuje kad se dodirne „Poveži s mojim telefonom“. Pogledajte [Povezani uređaji](#devices).",
  "**Delete me from everywhere**: Settings → Privacy and security → Delete me from everywhere deletes what the servers keep for the open space (its queues on the relays with the messages in them, what a relay holds for you to send later, files waiting there, invites nobody used), asks the Nostr relays through Tor to forget the keys your chats read on, and stops the space until you tap Start again. Your phone keeps everything. You can also sign out of Matrix and XMPP and delete the Nostr account made here. See [Delete me from everywhere](#forget).": "**Obriši me odasvud**: Postavke → Privatnost i sigurnost → Obriši me odasvud briše ono što serveri čuvaju za otvoreni prostor (njegove redove na relejima s porukama u njima, ono što relej drži da pošalje kasnije, datoteke koje tamo čekaju, pozivnice koje nitko nije upotrijebio), preko Tora traži od Nostr releja da zaborave ključeve na kojima tvoji razgovori čitaju i zaustavlja prostor dok ne dodirneš Pokreni ponovo. Tvoj telefon zadržava sve. Možeš se odjaviti i s Matrixa i XMPP-a te obrisati Nostr račun napravljen ovdje. Vidi [Obriši me odasvud](#forget).",
  "**Every relay queue on one list**: the queues a space keeps on the relays are gathered in one place, and the checks fail if a new kind of queue is made without being added there, so Delete me from everywhere cannot leave one behind.": "**Svaki red na releju na jednom popisu**: redovi koje prostor drži na relejima skupljeni su na jednom mjestu, a provjere padaju ako se napravi nova vrsta reda bez dodavanja tamo, pa Obriši me odasvud ne ostavlja nijedan.",
  "**Matrix, XMPP and Nostr on a linked computer**: linking a computer can bring this space's Matrix and XMPP accounts and the key of its Nostr chats over too, each signed in there as a new device of its own; for a computer linked already, tap Send the accounts under it on the phone. A Matrix server seldom lets the phone sign the computer in: the computer then asks for the Matrix password once, and the account's keys come from the phone, so no Security Key or check by emoji is needed. See [Linked devices](#devices).":
    "**Matrix, XMPP i Nostr na povezanom računaru**: povezivanje računara može donijeti i Matrix i XMPP račune ovog prostora te ključ njegovih Nostr razgovora, svaki prijavljen tamo kao novi uređaj za sebe; za računar koji je već povezan, dodirnite „Pošalji račune“ ispod njega na telefonu. Matrix server rijetko dopušta da telefon prijavi računar: računar tada jednom traži Matrix lozinku, a ključevi računa dolaze s telefona, pa nisu potrebni ni sigurnosni ključ ni provjera emojijima. Pogledajte [Povezani uređaji](#devices).",
  "**Only the SMS**: with Erevos locked, the SMS icon, the widget's SMS button and the notice of a new SMS ask for the password, then open only the SMS. Anything else, and the orange padlock **Unlock everything**, asks for it again, then opens all of Erevos. See [Password lock](#lock).":
    "**Samo SMS-ovi**: kad je Erevos zaključan, ikona SMS-a, dugme SMS na widgetu i obavijest o novom SMS-u traže lozinku, a zatim otvaraju samo SMS-ove. Sve ostalo, uključujući narandžasti lokot **Otključaj sve**, ponovo traži lozinku, a zatim otvara cijeli Erevos. Pogledajte [Zaključavanje lozinkom](#lock).",
  "**Nostr chats with a key brought from another app get their messages again**: Erevos reads where that app said your messages arrive, as that app does, instead of its own three relays, fetches the messages kept there and in older lists of the key, and reads a relay again when it stops sending. Before, such a key could show its chats with no past messages and get no new ones. See [Chats with other Nostr apps](#nostr-chats).":
    "**Nostr razgovori s ključem donesenim iz druge aplikacije ponovo dobivaju svoje poruke**: Erevos čita tamo gdje je ta aplikacija rekla da stižu vaše poruke, kao što to čini ta aplikacija, umjesto svoja tri relaya, dohvaća poruke koje se tamo čuvaju i u starijim popisima ključa, i ponovo čita relay kad prestane slati. Prije je takav ključ mogao prikazati svoje razgovore bez prošlih poruka i ne primati nove. Pogledajte [Razgovori s drugim Nostr aplikacijama](#nostr-chats).",
  "**Backups keep what closed chats need**: a backup now also holds what lets hidden chats ring a call and say a message came while they are closed, and a closed space say one came. So after a restore, on another phone too, **Ring calls when closed**, **Say when a message comes** and **Also while another space is open** go on as they were. See [Backups](#backup).":
    "**Rezervne kopije čuvaju ono što trebaju zatvoreni razgovori**: rezervna kopija sada čuva i ono čime skriveni razgovori zvone pozivima i javljaju da je stigla poruka dok su zatvoreni, te čime zatvoreni prostor javlja da je stigla poruka. Tako nakon vraćanja, i na drugom telefonu, **Zvonjava poziva kad su zatvoreni**, **Javi kad stigne poruka** i **I dok je otvoren drugi prostor** rade kao prije. Vidi [Rezervne kopije](#backup).",
  "**Open another space from the search**: type another space's password in **Search chats** on the home screen and press Enter: the open space closes, nothing of it stays, and the other opens, as with **Lock now** and its password. It takes as long whatever is typed, and a wrong password, or the open space's own, is just a search. See [Second password](#second).":
    "**Otvaranje drugog prostora iz pretrage**: upiši lozinku drugog prostora u **Traži razgovore** na početnom ekranu i pritisni Enter: otvoreni prostor se zatvara, ništa od njega ne ostaje, i otvara se drugi, kao sa **Zaključaj sada** i njegovom lozinkom. Traje jednako dugo što god upišeš, a pogrešna lozinka, ili lozinka otvorenog prostora, samo je pretraga. Vidi [Druga lozinka](#second).",
  "**A dot for unread messages elsewhere, if you want it**: hidden chats with **Receive while closed** can show a small dot on the magnifier of **Search chats** while they have a message unread (their switch **Dot for unread messages**), and a space set to say a message came while another is open can show one on the padlock at the top of the other spaces' chats (**Dot in the other spaces**). Never how many, nor where; off unless you turn it on. See [Hidden chats](#hidden).":
    "**Tačka za nepročitano na drugom mjestu, ako je želite**: skriveni razgovori s **Primanje dok su zatvoreni** mogu pokazati malu tačku na lupi u **Traži razgovore** dok imaju nepročitanu poruku (njihov prekidač **Tačka za nepročitano**), a prostor koji javlja da je stigla poruka dok je otvoren drugi može pokazati jednu na lokotu iznad razgovora drugih prostora (**Tačka u drugim prostorima**). Nikad koliko, ni gdje; isključeno, osim ako uključite. Pogledajte [Skriveni razgovori](#hidden).",
  "**Joining takes only the invite**: on a phone with no relay yet, **New chat** shows one way in, **I have an invite**. Signing in with LPHL, **Start without a relay** and the relay's settings are under **For advanced users**, for whoever looks for them. And an invite to your relay gives the relay only a name of random letters and digits for the phone it lets in: the name you type stays on your phone, where your list of invites shows it. See [Chat through a relay](#relay).":
    "**Za ulazak je dovoljna pozivnica**: na telefonu koji još nema relay, **Novi razgovor** pokazuje jedan način ulaska, **Imam pozivnicu**. Prijava preko LPHL-a, **Počnite bez relaya** i postavke relaya su pod **Za napredne korisnike**, za onoga ko ih traži. A pozivnica na vaš relay daje relayu samo ime od nasumičnih slova i cifara za telefon koji pušta unutra: ime koje upišete ostaje na vašem telefonu, gdje ga pokazuje vaš spisak pozivnica. Pogledajte [Razgovor preko relaya](#relay).",
  "**Invited phones stay**: on a relay of this version, a phone you invited keeps its access even once yours goes, and so do the phones it invited; taking back an invite cuts off that one phone alone. See [Chat through a relay](#relay).":
    "**Pozvani telefoni ostaju**: na relayu ove verzije, telefon koji ste pozvali zadržava svoj pristup čak i kad vaš nestane, a isto tako i telefoni koje je on pozvao; povlačenje pozivnice isključuje samo taj jedan telefon. Pogledajte [Razgovor preko relaya](#relay).",
  "**Backups bring the phone back as it was**: a backup now holds the photos, files and voice messages too, in files of their own beside it, each sealed and bound to its backup; and the panic password, the settings that go with you, the Phone's quick replies and the calls it turns away, the SMS for later and automatic backups with their server, but not their folder. An SMS for later whose time passed before the restore waits for you to send it or delete it. What stays with each phone, as the fingerprint, the folders and what Android allows, never comes back: after a restore, Android's permissions open for the modules that are on. See [Backups](#backup).":
    "**Rezervne kopije vraćaju telefon kakav je bio**: rezervna kopija sada sadrži i fotografije, datoteke i glasovne poruke, u zasebnim datotekama pored nje, svaku zapečaćenu i vezanu za svoju kopiju; i lozinku za paniku, postavke koje idu s vama, brze odgovore Telefona i pozive koje odbija, SMS poruke za kasnije i automatske rezervne kopije s njihovim serverom, ali ne i njihov folder. SMS za kasnije čije je vrijeme prošlo prije vraćanja čeka da ga pošaljete ili obrišete. Ono što ostaje uz svaki telefon, kao otisak prsta, folderi i ono što Android dozvoljava, nikad se ne vraća: nakon vraćanja otvaraju se Androidove dozvole za uključene module. Pogledajte [Rezervne kopije](#backup).",
  "**A newer backup asks for a newer Erevos**: a backup made by a newer Erevos than yours is refused, with nothing changed, and Erevos asks you to update to the latest version first. An Erevos from before 6.0.0 does not open backups from 6.0.0 on: update it, then restore. See [Backups](#backup).":
    "**Novija rezervna kopija traži noviji Erevos**: kopija koju je napravio noviji Erevos od vašeg se odbija, a ništa se ne mijenja, i Erevos traži da ga prvo ažurirate na najnoviju verziju. Erevos prije 6.0.0 ne otvara kopije od 6.0.0 nadalje: ažurirajte ga, pa vratite kopiju. Vidi [Rezervne kopije](#backup).",
  "**Shared into the Collection with no plain copy**: a photo or file another app shares with Erevos is encrypted as it comes in, before **Send to** opens, so on its way into the Collection it never lies unencrypted on the phone. See [Collection](#collection).": "**Dijeljenje u Zbirku bez nešifrirane kopije**: fotografija ili datoteka koju druga aplikacija podijeli s Erevosom šifrira se čim stigne, prije nego što se otvori **Pošalji u**, pa na putu u Zbirku nikad ne leži nešifrirana na telefonu. Pogledajte [Zbirku](#collection).",
  "**See a file come from the WebDAV server**: a file of the Collection that is not on this device, as after a backup restored on a new phone, shows how much of it has come from the server, and **Cancel** stops it; what came stays, and the next time only the rest comes. Music, videos, PDFs and **Open with another app** fetch it first too, instead of failing. See [Collection](#collection).": "**Gledaj kako datoteka stiže sa WebDAV servera**: datoteka Zbirke koje nema na ovom uređaju, kao nakon rezervne kopije vraćene na novom telefonu, pokazuje koliko je od nje stiglo sa servera, a **Otkaži** je zaustavlja; ono što je stiglo ostaje, a sljedeći put stiže samo ostatak. Muzika, video snimci, PDF-ovi i **Otvori drugom aplikacijom** je takođe prvo preuzimaju, umjesto da ne uspiju. Pogledajte [Zbirku](#collection).",
  "**Backups skip what is on the WebDAV server after a restart too**: that a Collection's copies on its server are complete is kept with it, so a backup made after Erevos starts again still leaves its pieces out, as long as no file was added or deleted since. **The connection works.** now shows in the colour of success, not of a warning. See [Collection](#collection).": "**Rezervne kopije i nakon ponovnog pokretanja izostavljaju ono što je na WebDAV serveru**: to da su kopije Zbirke na njenom serveru potpune čuva se uz nju, pa rezervna kopija napravljena nakon što se Erevos ponovo pokrene i dalje izostavlja njene dijelove, dok god od tada nije dodata ni obrisana nijedna datoteka. **Veza radi.** sada se prikazuje u boji uspjeha, a ne upozorenja. Pogledajte [Zbirku](#collection).",
};
